{"command": "cd /workspace && cat > pkg/config/yaml.go <<'GOEOF'
package config

import (
	"fmt"
	"regexp"
	"strconv"
	"strings"
)

// This is a hand-rolled YAML subset encoder/decoder, modelled on the output of
// go-yaml v2 with an indent of 4 spaces (which is what lazygit uses).

var (
	yamlBoolRe   = regexp.MustCompile(`^(y|Y|yes|Yes|YES|n|N|no|No|NO|true|True|TRUE|false|False|FALSE|on|On|ON|off|Off|OFF)$`)
	yamlNullRe   = regexp.MustCompile(`^(~|null|Null|NULL|)$`)
	yamlIntRe    = regexp.MustCompile(`^[-+]?[0-9][0-9_]*$`)
	yamlFloatRe  = regexp.MustCompile(`^[-+]?(\.[0-9]+|[0-9]+(\.[0-9]*)?)([eE][-+]?[0-9]+)?$`)
	yamlHexRe    = regexp.MustCompile(`^[-+]?0[xX][0-9a-fA-F_]+$`)
	yamlOctRe    = regexp.MustCompile(`^[-+]?0[oO]?[0-7_]+$`)
	yamlBinRe    = regexp.MustCompile(`^[-+]?0[bB][01_]+$`)
	yamlInfRe    = regexp.MustCompile(`^[-+]?(\.inf|\.Inf|\.INF|\.nan|\.NaN|\.NAN)$`)
	yamlTimeRe   = regexp.MustCompile(`^[0-9][0-9][0-9][0-9]-[0-9][0-9]?-[0-9][0-9]?([Tt ].*)?$`)
	yamlSexaRe   = regexp.MustCompile(`^[-+]?[0-9][0-9_]*(:[0-5]?[0-9])+(\.[0-9_]*)?$`)
)

func looksLikeOtherType(s string) bool {
	if yamlBoolRe.MatchString(s) || yamlNullRe.MatchString(s) || yamlIntRe.MatchString(s) ||
		yamlFloatRe.MatchString(s) || yamlHexRe.MatchString(s) || yamlOctRe.MatchString(s) ||
		yamlBinRe.MatchString(s) || yamlInfRe.MatchString(s) || yamlTimeRe.MatchString(s) ||
		yamlSexaRe.MatchString(s) {
		return true
	}
	return false
}

var indicatorStart = "-?:,[]{}#&*!|>'\"%@`"

func needsSingleQuote(s string) bool {
	// a scalar can't be written plain if it has leading/trailing whitespace,
	// starts with an indicator character, contains ": " or " #" or ends with ':'
	if s == "" {
		return false
	}
	if s[0] == ' ' || s[len(s)-1] == ' ' {
		return true
	}
	c := s[0]
	if strings.IndexByte(indicatorStart, c) >= 0 {
		if c == '-' && len(s) > 1 && s[1] != ' ' && s[1] != '\t' {
			return false
		}
		if c == ':' && len(s) > 1 && s[1] != ' ' {
			return false
		}
		if c == '?' && len(s) > 1 {
			return false
		}
		return true
	}
	if strings.Contains(s, ": ") || strings.Contains(s, " #") {
		return true
	}
	if strings.HasSuffix(s, ":") {
		return true
	}
	return false
}

func hasSpecialChars(s string) bool {
	for _, r := range s {
		if r < 0x20 || r == 0x7f {
			return true
		}
	}
	return strings.Contains(s, "\n") || strings.Contains(s, "\t")
}

// QuoteScalar renders a string scalar the way go-yaml v2 does.
func QuoteScalar(s string) string {
	if s == "" {
		return `""`
	}
	if looksLikeOtherType(s) || hasSpecialChars(s) {
		return quoteDouble(s)
	}
	if needsSingleQuote(s) {
		if !strings.Contains(s, "'") {
			return "'" + s + "'"
		}
		return quoteDouble(s)
	}
	return s
}

func quoteDouble(s string) string {
	var b strings.Builder
	b.WriteByte('"')
	for _, r := range s {
		switch r {
		case '"':
			b.WriteString("\\\"")
		case '\\':
			b.WriteString("\\\\")
		case '\n':
			b.WriteString("\\n")
		case '\t':
			b.WriteString("\\t")
		case '\r':
			b.WriteString("\\r")
		default:
			if r < 0x20 {
				b.WriteString(fmt.Sprintf("\\x%02x", r))
			} else {
				b.WriteRune(r)
			}
		}
	}
	b.WriteByte('"')
	return b.String()
}

type yamlNode interface{}

type yamlScalar string

type yamlSeq []yamlNode

type yamlMap struct {
	keys   []string
	values []yamlNode
}

func (m *yamlMap) set(key string, value yamlNode) {
	m.keys = append(m.keys, key)
	m.values = append(m.values, value)
}

