	return yamlBoolRe.MatchString(s) || yamlNullRe.MatchString(s) || yamlNumRe.MatchString(s) ||
		yamlRadix.MatchString(s) || yamlInfRe.MatchString(s) || yamlTimeRe.MatchString(s) ||
		yamlSexaRe.MatchString(s)
