const indicatorStart = "-?:,[]{}#&*!|>'\"%@`"

func plainUnsafe(s string) bool {
	if s == "" {
		return false
	}
	if s[0] == ' ' || s[len(s)-1] == ' ' || s[len(s)-1] == ':' {
		return true
	}
	c := s[0]
	if strings.IndexByte(indicatorStart, c) >= 0 {
		if c == '-' && len(s) > 1 && s[1] != ' ' && s[1] != '\t' {
			return false
		}
		if c == ':' && len(s) > 1 && s[1] != ' ' {
			return false
		}
		if c == '?' && len(s) > 1 {
			return false
		}
		return true
	}
	return strings.Contains(s, ": ") || strings.Contains(s, " #")
}

func hasSpecialChars(s string) bool {
	if strings.ContainsAny(s, "\n\t") {
		return true
	}
	for _, r := range s {
		if r < 0x20 || r == 0x7f {
			return true
		}
	}
	return false
}

