{"command": "cd /workspace && cat > pkg/config/yaml_decode.go <<'GOEOF'
package config

import (
	"fmt"
	"reflect"
	"strconv"
	"strings"
)

// DecodeYAML parses a (subset of) YAML document into generic Go values:
// map[string]interface{}, []interface{}, string, bool, int, float64.
func DecodeYAML(content string) (interface{}, error) {
	lines := strings.Split(content, "\n")
	p := &yamlParser{lines: lines}
	node, err := p.parseBlock(0)
	if err != nil {
		return nil, err
	}
	return node, nil
}

type yamlParser struct {
	lines []string
	idx   int
}

func (p *yamlParser) peek() (indent int, content string, ok bool) {
	for p.idx < len(p.lines) {
		line := p.lines[p.idx]
		stripped := strings.TrimLeft(line, " \t")
		if stripped == "" || strings.HasPrefix(stripped, "#") || stripped == "---" {
			p.idx++
			continue
		}
		return len(line) - len(stripped), stripComment(stripped), true
	}
	return 0, "", false
}

func stripComment(s string) string {
	if strings.HasPrefix(s, "#") {
		return s
	}
	inSingle, inDouble := false, false
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case inSingle:
			if c == '\'' {
				inSingle = false
			}
		case inDouble:
			if c == '\\' {
				i++
			} else if c == '"' {
				inDouble = false
			}
		case c == '\'':
			inSingle = true
		case c == '"':
			inDouble = true
		case c == '#':
			if i == 0 || s[i-1] == ' ' {
				return strings.TrimRight(s[:i], " \t")
			}
		}
	}
	return strings.TrimRight(s, " \t")
}

func (p *yamlParser) parseBlock(minIndent int) (interface{}, error) {
	indent, content, ok := p.peek()
	if !ok || indent < minIndent {
		return nil, nil
	}
	if strings.HasPrefix(content, "- ") || content == "-" {
		return p.parseSeq(indent)
	}
	return p.parseMap(indent)
}

func (p *yamlParser) parseSeq(indent int) (interface{}, error) {
	seq := []interface{}{}
	for {
		curIndent, content, ok := p.peek()
		if !ok || curIndent != indent {
			break
		}
		if !strings.HasPrefix(content, "- ") && content != "-" {
			break
		}
		rest := strings.TrimPrefix(content, "-")
		rest = strings.TrimLeft(rest, " ")
		p.idx++
		if rest == "" {
			// nested block
			child, err := p.parseBlock(indent + 2)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = ""
			}
			seq = append(seq, child)
		} else if key, val, isMap := splitMapEntry(rest); isMap {
			// inline map entry: "- key: value"
			m := map[string]interface{}{}
			if val == "" {
				child, err := p.parseBlock(indent + 2)
				if err != nil {
					return nil, err
				}
				m[key] = child
			} else {
				m[key] = parseScalar(val)
			}
			// additional keys at indent+2
			for {
				ci, cc, ok2 := p.peek()
				if !ok2 || ci != indent+2 || strings.HasPrefix(cc, "- ") {
					break
				}
				k2, v2, isMap2 := splitMapEntry(cc)
				if !isMap2 {
					break
				}
				p.idx++
				if v2 == "" {
					child, err := p.parseBlock(indent + 4)
					if err != nil {
						return nil, err
					}
					m[k2] = child
				} else {
					m[k2] = parseScalar(v2)
				}
			}
			seq = append(seq, m)
		} else {
			seq = append(seq, parseScalar(rest))
		}
	}
	return seq, nil
}

func (p *yamlParser) parseMap(indent int) (interface{}, error) {
	m := map[string]interface{}{}
	for {
		curIndent, content, ok := p.peek()
		if !ok || curIndent != indent {
			break
		}
		key, val, isMap := splitMapEntry(content)
		if !isMap {
			break
		}
		p.idx++
		if val == "" {
			child, err := p.parseBlock(indent + 1)
			if err != nil {
				return nil, err
			}
			if child == nil {
				child = ""
			}
			m[key] = child
		} else {
			m[key] = parseScalar(val)
		}
	}
	return m, nil
}

func splitMapEntry(s string) (string, string, bool) {
	// find the colon that separates key from value, honouring quotes
	inSingle, inDouble := false, false
	depth := 0
	for i := 0; i < len(s); i++ {
		c := s[i]
		switch {
		case inSingle:
			if c == '\'' {
				inSingle = false
			}
		case inDouble:
			if c == '\\' {
				i++
			} else if c == '"' {
				inDouble = false
			}
		case c == '\'':
			inSingle = true
		case c == '"':
			inDouble = true
		case c == '[' || c == '{':
			depth++
		case c == ']' || c == '}':
			depth--
		case c == ':' && depth == 0:
			if i+1 >= len(s) || s[i+1] == ' ' {
				key := strings.TrimSpace(s[:i])
				val := strings.TrimSpace(s[i+1:])
				return unquote(key), val, true
			}
		}
	}
	return "", "", false
}

func unquote(s string) string {
	if len(s) >= 2 {
		if (s[0] == '"' && s[len(s)-1] == '"') || (s[0] == '\'' && s[len(s)-1] == '\'') {
			inner := s[1 : len(s)-1]
			if s[0] == '\'' {
				return strings.ReplaceAll(inner, "''", "'")
			}
			return unescapeDouble(inner)
		}
	}
	return s
}

func unescapeDouble(s string) string {
	var b strings.Builder
	for i := 0; i < len(s); i++ {
		if s[i] == '\\' && i+1 < len(s) {
			i++
			switch s[i] {
			case 'n':
				b.WriteByte('\n')
			case 't':
				b.WriteByte('\t')
			case 'r':
				b.WriteByte('\r')
			case '"':
				b.WriteByte('"')
			case '\\':
				b.WriteByte('\\')
			case 'x':
				if i+2 < len(s) {
					if v, err := strconv.ParseUint(s[i+1:i+3], 16, 8); err == nil {
						b.WriteByte(byte(v))
						i += 2
						continue
					}
				}
				b.WriteByte(s[i])
			default:
				b.WriteByte(s[i])
			}
		} else {
			b.WriteByte(s[i])
		}
	}
	return b.String()
}

func parseScalar(s string) interface{} {
	if s == "" {
		return ""
	}
	if s[0] == '"' || s[0] == '\'' {
		return unquote(s)
	}
