	m, ok := node.(map[string]interface{})
	if !ok {
		return
	}
	applyMapToValue(reflect.ValueOf(cfg).Elem(), m)
}

func applyMapToValue(structVal reflect.Value, m map[string]interface{}) {
	t := structVal.Type()
	for i := 0; i < t.NumField(); i++ {
		f := t.Field(i)
		tag := f.Tag.Get("yaml")
		if tag == "-" {
			continue
		}
		name := strings.Split(tag, ",")[0]
		if name == "" {
			name = f.Name
		}
		val, ok := m[name]
		if !ok {
			continue
		}
		setValue(structVal.Field(i), val)
	}
}

func setValue(field reflect.Value, val interface{}) {
	if val == nil {
		return
	}
	switch field.Kind() {
	case reflect.String:
		switch v := val.(type) {
		case string:
			field.SetString(v)
		case bool:
			field.SetBool(v)
		case int:
			field.SetString(strconv.Itoa(v))
		}
	case reflect.Bool:
		if b, ok := val.(bool); ok {
			field.SetBool(b)
		} else if s, ok := val.(string); ok {
			b, err := strconv.ParseBool(s)
			if err == nil {
				field.SetBool(b)
			}
		}
	case reflect.Int, reflect.Int8, reflect.Int16, reflect.Int32, reflect.Int64:
		switch v := val.(type) {
		case int:
			field.SetInt(int64(v))
		case float64:
			field.SetInt(int64(v))
		case string:
			if i, err := strconv.ParseInt(v, 10, 64); err == nil {
				field.SetInt(i)
			}
		}
	case reflect.Float32, reflect.Float64:
		switch v := val.(type) {
		case float64:
			field.SetFloat(v)
		case int:
			field.SetFloat(float64(v))
		case string:
			if f, err := strconv.ParseFloat(v, 64); err == nil {
				field.SetFloat(f)
			}
		}
	case reflect.Slice:
		list, ok := val.([]interface{})
		if !ok {
			return
		}
		slice := reflect.MakeSlice(field.Type(), len(list), len(list))
		for i, item := range list {
			setValue(slice.Index(i), item)
		}
		field.Set(slice)
	case reflect.Map:
		mm, ok := val.(map[string]interface{})
		if !ok {
			return
		}
		newMap := reflect.MakeMap(field.Type())
		for k, v := range mm {
			elem := reflect.New(field.Type().Elem()).Elem()
			setValue(elem, v)
			newMap.SetMapIndex(reflect.ValueOf(k), elem)
		}
		field.Set(newMap)
	case reflect.Struct:
		if mm, ok := val.(map[string]interface{}); ok {
			applyMapToValue(field, mm)
		}
	case reflect.Ptr:
		if field.IsNil() {
			field.Set(reflect.New(field.Type().Elem()))
		}
		if mm, ok := val.(map[string]interface{}); ok {
			applyMapToValue(field.Elem(), mm)
		}
	default:
		_ = fmt.Sprint
	}
}
GOEOF
echo ok"}

