package state

import (
	"os"
	"time"

	"github.com/jesseduffield/lazygit/pkg/config"
)

// AppState is the persisted state of the app (state.yml in the state dir).
type AppState struct {
	LastUpdateCheck         int      `yaml:"lastupdatecheck"`
	RecentRepos             []string `yaml:"recentrepos"`
	StartupPopupVersion     int      `yaml:"startuppopupversion"`
	CommonState             CommonState `yaml:",inline"`
	DidShowHunkStagingHint  bool     `yaml:"didshowhunkstaginghint"`
	LastVersion             string   `yaml:"lastversion"`
	CustomCommandsHistory   []string `yaml:"customcommandshistory"`
	HideCommandLog          bool     `yaml:"hidecommandlog"`
}

type CommonState struct {
}

// AppStateDefaults returns the initial app state.
func AppStateDefaults() *AppState {
	return &AppState{
		LastUpdateCheck:       0,
		RecentRepos:           []string{},
		StartupPopupVersion:   0,
		DidShowHunkStagingHint: false,
		LastVersion:           "",
		CustomCommandsHistory: []string{},
		HideCommandLog:        false,
	}
}

// LoadAppState loads the app state from disk, returning defaults if absent.
func LoadAppState() *AppState {
	path := AppStateFilepath()
	content, err := os.ReadFile(path)
	if err != nil {
		return AppStateDefaults()
	}
	node, err := config.DecodeYAML(string(content))
	if err != nil {
		return AppStateDefaults()
	}
	state := AppStateDefaults()
	if m, ok := node.(map[string]interface{}); ok {
		config.ApplyMapToValue(reflectValue(state), m)
	}
	return state
}

// AppStateFilepath returns the path of the state file.
func AppStateFilepath() string {
	return config.StateDir() + "/state.yml"
}

// SaveAppState writes the app state to disk.
func (state *AppState) Save() {
	os.MkdirAll(config.StateDir(), 0o700)
	os.WriteFile(AppStateFilepath(), []byte(config.EncodeYAML(state)), 0o644)
}

// UpdateLastUpdateCheck records that we checked for an update now.
func (state *AppState) UpdateLastUpdateCheck() {
	state.LastUpdateCheck = int(time.Now().Unix())
}
