{"command": "cd /workspace && cat > pkg/ui/terminal.go <<'GOEOF'
package ui

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

// Terminal handles raw terminal mode, size queries and input.
type Terminal struct {
	tty        *os.File
	origState  *Termios
	rawState   *Termios
	out        *os.File
	Width      int
	Height     int
	inBuf      []byte
	hasMouse   bool
}

type Termios struct {
	Iflag, Oflag, Cflag, Lflag uint32
	Line                       uint8
	Cc                         [32]uint8
	Ispeed, Ospeed             uint32
}

const (
	tcgets = 0x5401
	tcsets = 0x5402
	tiocgwinsz = 0x5413
)

type winsize struct {
	Row, Col, Xpixel, Ypixel uint16
}

func ioctl(fd uintptr, req uintptr, arg uintptr) error {
	_, _, errno := syscall.Syscall(syscall.SYS_IOCTL, fd, req, arg)
	if errno != 0 {
		return errno
	}
	return nil
}

func openTTY() (*os.File, error) {
	for _, f := range []string{"/dev/tty"} {
		file, err := os.OpenFile(f, os.O_RDWR, 0)
		if err == nil {
			return file, nil
		}
	}
	return nil, fmt.Errorf("open /dev/tty: no such device or address")
}

// NewTerminal opens the terminal and puts it in raw mode.
func NewTerminal() (*Terminal, error) {
	tty, err := openTTY()
	if err != nil {
		return nil, err
	}
	t := &Terminal{tty: tty, out: os.Stdout}
	state, err := t.getAttr(tty.Fd())
	if err != nil {
		return nil, err
	}
	t.origState = state
	raw := *state
	// cfmakeraw
	raw.Iflag &^= syscall.IGNBRK | syscall.BRKINT | syscall.PARMRK | syscall.ISTRIP | syscall.INLCR | syscall.IGNCR | syscall.ICRNL | syscall.IXON
	raw.Oflag &^= syscall.OPOST
	raw.Lflag &^= syscall.ECHO | syscall.ECHONL | syscall.ICANON | syscall.ISIG | syscall.IEXTEN
	raw.Cflag &^= syscall.CSIZE | syscall.PARENB
	raw.Cflag |= syscall.CS8
	raw.Cc[syscall.VMIN] = 1
	raw.Cc[syscall.VTIME] = 0
	t.rawState = &raw
	if err := t.setAttr(tty.Fd(), &raw); err != nil {
		return nil, err
	}
	w, h := t.Size()
	t.Width, t.Height = w, h
	return t, nil
}

func (t *Terminal) getAttr(fd uintptr) (*Termios, error) {
	var tio Termios
	if err := ioctl(fd, tcgets, uintptr(unsafe.Pointer(&tio))); err != nil {
		return nil, err
	}
	return &tio, nil
}

func (t *Terminal) setAttr(fd uintptr, tio *Termios) error {
	return ioctl(fd, tcsets, uintptr(unsafe.Pointer(tio)))
}

// Size returns the terminal width and height.
func (t *Terminal) Size() (int, int) {
	var ws winsize
	if err := ioctl(t.tty.Fd(), tiocgwinsz, uintptr(unsafe.Pointer(&ws))); err != nil {
		if err2 := ioctl(os.Stdout.Fd(), tiocgwinsz, uintptr(unsafe.Pointer(&ws))); err2 != nil {
			return 80, 24
		}
	}
	return int(ws.Col), int(ws.Row)
}

// RefreshSize re-reads the terminal size.
func (t *Terminal) RefreshSize() (int, int) {
	w, h := t.Size()
	t.Width, t.Height = w, h
	return w, h
}

// Enter enters the alternate screen and hides the cursor.
func (t *Terminal) Enter() {
	fmt.Fprint(t.out, "\x1b[?1049h\x1b[?25l\x1b[2J\x1b[H")
}

// Exit leaves the alternate screen and restores the terminal state.
func (t *Terminal) Exit() {
	fmt.Fprint(t.out, "\x1b[?25h\x1b[?1049l")
	t.tty.Write([]byte{})
	if t.origState != nil {
		t.setAttr(t.tty.Fd(), t.origState)
	}
}

// Suspend restores the terminal to its original state.
func (t *Terminal) Suspend() {
	fmt.Fprint(t.out, "\x1b[?25h\x1b[?1049l")
	if t.origState != nil {
		t.setAttr(t.tty.Fd(), t.origState)
	}
}

// Resume re-enters raw mode.
func (t *Terminal) Resume() {
	if t.rawState != nil {
		t.setAttr(t.tty.Fd(), t.rawState)
	}
	fmt.Fprint(t.out, "\x1b[?1049h\x1b[?25l")
}

// Write writes raw bytes to the terminal.
func (t *Terminal) Write(b []byte) (int, error) {
	return t.out.Write(b)
}

// Read reads bytes from the tty.
func (t *Terminal) Read(b []byte) (int, error) {
	return t.tty.Read(b)
}

// SetMouse enables or disables mouse reporting.
func (t *Terminal) SetMouse(on bool) {
	t.hasMouse = on
	if on {
		fmt.Fprint(t.out, "\x1b[?1002h\x1b[?1006h")
	} else {
		fmt.Fprint(t.out, "\x1b[?1002l\x1b[?1006l")
	}
}

// Close cleans up.
func (t *Terminal) Close() {
	t.Exit()
	if t.tty != nil {
		t.tty.Close()
	}
}
GOEOF
go build ./pkg/... && echo OK"}

