package ui

import (
	"strconv"
	"strings"
)

// Style describes the appearance of a text run.
type Style struct {
	Fg        string // "" means inherit/default
	Bg        string
	Bold      bool
	Underline bool
	Reverse   bool
	Faint     bool
}

// DefaultStyle is the plain style.
