var namedColors = map[string]int{
	"black": 0, "red": 1, "green": 2, "yellow": 3, "blue": 4,
	"magenta": 5, "cyan": 6, "white": 7, "default": -1,
}

var brightColors = map[string]int{
	"black": 8, "red": 9, "green": 10, "yellow": 11, "blue": 12,
	"magenta": 13, "cyan": 14, "white": 15, "default": -1,
}

// ParseStyle parses a list of color/attribute names into a Style.
func ParseStyle(parts []string) Style {
	var s Style
	for _, p := range parts {
		switch strings.ToLower(p) {
		case "bold":
			s.Bold = true
		case "underline":
			s.Underline = true
		case "reverse":
			s.Reverse = true
		case "faint":
			s.Faint = true
		default:
			if s.Fg == "" {
				s.Fg = strings.ToLower(p)
			} else if s.Bg == "" {
				s.Bg = strings.ToLower(p)
			}
		}
	}
	return s
}

// ColorCode returns the SGR code for a color name, as fg or bg.
func ColorCode(name string, bg bool, bright bool) string {
	if name == "" || name == "default" {
		if bg {
			return "49"
		}
		return "39"
	}
	// 256 color / truecolor forms
	if strings.HasPrefix(name, "truecolor:") || strings.HasPrefix(name, "#") {
		hex := strings.TrimPrefix(strings.TrimPrefix(name, "truecolor:"), "#")
		if len(hex) == 6 {
			r, _ := strconv.ParseInt(hex[0:2], 16, 32)
			g, _ := strconv.ParseInt(hex[2:4], 16, 32)
			b, _ := strconv.ParseInt(hex[4:6], 16, 32)
			prefix := "38"
			if bg {
				prefix = "48"
			}
			return prefix + ";2;" + strconv.Itoa(int(r)) + ";" + strconv.Itoa(int(g)) + ";" + strconv.Itoa(int(b))
		}
	}
	if n, err := strconv.Atoi(name); err == nil {
		if n >= 0 && n < 256 {
			prefix := "38"
			if bg {
				prefix = "48"
			}
			return prefix + ";5;" + strconv.Itoa(n)
		}
	}
	table := namedColors
	if bright {
		table = brightColors
	}
	n, ok := table[strings.ToLower(name)]
	if !ok {
		if bg {
			return "49"
		}
		return "39"
	}
	if n < 0 {
		if bg {
			return "49"
		}
		return "39"
	}
	if bg {
		return strconv.Itoa(n + 40)
	}
	return strconv.Itoa(n + 30)
