// Bright returns the bright version of a color name.
func Bright(name string) string {
	if name == "" || name == "default" {
		return name
	}
	if strings.HasPrefix(name, "#") || strings.HasPrefix(name, "truecolor:") {
		return name
	}
	if _, err := strconv.Atoi(name); err == nil {
		return name
	}
	if _, ok := namedColors[name]; ok {
		return name
	}
	return name
}

// IsBrightable reports whether a color name has a bright variant.
func IsBrightable(name string) bool {
	_, ok := namedColors[name]
	return ok && name != "default" && name != ""
}

// Encode emits the escape codes to move from `from` to `to`.
// It follows the pattern observed in lazygit: attribute changes reset with
// \x1b[0m followed by explicit fg/bg codes.
func Encode(from, to Style) string {
	var b strings.Builder
	attrsFrom := attrBits(from)
	attrsTo := attrBits(to)
	if attrsFrom != attrsTo {
		if attrsTo&attrBold != 0 && attrsFrom&attrBold == 0 {
			b.WriteString("\x1b[1m")
		}
		if attrsTo&attrUnderline != 0 && attrsFrom&attrUnderline == 0 {
			b.WriteString("\x1b[4m")
		}
		if attrsTo&attrReverse != 0 && attrsFrom&attrReverse == 0 {
			b.WriteString("\x1b[7m")
		}
		if attrsTo&attrFaint != 0 && attrsFrom&attrFaint == 0 {
			b.WriteString("\x1b[2m")
		}
		if attrsTo < attrsFrom {
			b.WriteString("\x1b[0m")
			b.WriteString("\x1b[" + ColorCode(fgName(to), false, to.Bright) + "m")
			b.WriteString("\x1b[" + ColorCode(bgName(to), true, false) + "m")
			return b.String()
		}
	}
	if from.Fg != to.Fg || from.Bright != to.Bright {
		b.WriteString("\x1b[" + ColorCode(fgName(to), false, to.Bright) + "m")
	}
	if from.Bg != to.Bg {
		b.WriteString("\x1b[" + ColorCode(bgName(to), true, false) + "m")
	}
	return b.String()
}

func fgName(s Style) string {
	if s.Fg == "" {
		return "default"
	}
	return s.Fg
}

func bgName(s Style) string {
	if s.Bg == "" {
		return "default"
	}
	return s.Bg
}

const (
	attrBold = 1 << iota
	attrUnderline
	attrReverse
	attrFaint
)

func attrBits(s Style) int {
	n := 0
	if s.Bold {
		n |= attrBold
	}
	if s.Underline {
		n |= attrUnderline
	}
	if s.Reverse {
		n |= attrReverse
	}
	if s.Faint {
		n |= attrFaint
	}
	return n
}

// WithBright returns a copy of the style with fg colors brightened.
func (s Style) WithBright() Style {
	if !IsBrightable(s.Fg) {
		return s
	}
	out := s
	out.Bright = true
	return out
}
