package gui

import (
	"strconv"
	"strings"

	"github.com/jesseduffield/lazygit/pkg/ui"
)

// Cell is a single screen cell.
type Cell struct {
	Ch    rune
	Style ui.Style
}

// Screen is a grid of cells.
type Screen struct {
	W, H  int
	cells []Cell
}

// NewScreen creates a screen of the given size.
func NewScreen(w, h int) *Screen {
	s := &Screen{W: w, H: h}
	s.cells = make([]Cell, w*h)
	for i := range s.cells {
		s.cells[i] = Cell{Ch: ' ', Style: ui.DefaultStyle}
	}
	return s
}

// SetCell writes a single cell.
func (s *Screen) SetCell(x, y int, ch rune, style ui.Style) {
	if x < 0 || y < 0 || x >= s.W || y >= s.H {
		return
	}
	s.cells[y*s.W+x] = Cell{Ch: ch, Style: style}
}

// SetText writes a string at a position, clipped to the given width.
func (s *Screen) SetText(x, y, w int, text string, style ui.Style) {
	col := x
	for _, r := range text {
		if col >= x+w {
			break
		}
		if r == '\t' {
			r = ' '
		}
		s.SetCell(col, y, r, style)
		col++
	}
}

// SetStyled writes styled runs at a position.
func (s *Screen) SetStyled(x, y, w int, runs []Run) {
	col := x
	for _, r := range runs {
		for _, ch := range r.Text {
			if col >= x+w {
				return
			}
			if ch == '\t' {
				ch = ' '
			}
			s.SetCell(col, y, ch, r.Style)
			col++
		}
	}
}

// Flush writes the screen to the terminal, emitting style diffs.
func (s *Screen) Flush(out *strings.Builder) {
	cur := ui.Style{Fg: "default", Bg: "default"}
	for y := 0; y < s.H; y++ {
		out.WriteString("\x1b[")
		out.WriteString(strconv.Itoa(y + 1))
		out.WriteString(";1H")
		lastNonSpace := -1
		for x := s.W - 1; x >= 0; x-- {
			if s.cells[y*s.W+x].Ch != ' ' {
				lastNonSpace = x
				break
			}
		}
		for x := 0; x <= lastNonSpace; x++ {
			c := s.cells[y*s.W+x]
			if c.Style != cur {
				out.WriteString(encodeStyle(cur, c.Style))
				cur = c.Style
			}
			out.WriteRune(c.Ch)
		}
	}
	out.WriteString("\x1b[0m")
}

func encodeStyle(from, to ui.Style) string {
	var b strings.Builder
	// attributes
	if (to.Bold || to.Underline || to.Reverse || to.Faint) && !from.Bold && !from.Underline && !from.Reverse && !from.Faint {
		if to.Bold {
			b.WriteString("\x1b[1m")
		}
		if to.Faint {
			b.WriteString("\x1b[2m")
		}
		if to.Underline {
			b.WriteString("\x1b[4m")
		}
		if to.Reverse {
			b.WriteString("\x1b[7m")
		}
	} else if !(to.Bold || to.Underline || to.Reverse || to.Faint) && (from.Bold || from.Underline || from.Reverse || from.Faint) {
		b.WriteString("\x1b[0m")
		b.WriteString("\x1b[" + ui.ColorCode(fgOf(to), false, to.Bright) + "m")
		b.WriteString("\x1b[" + ui.ColorCode(bgOf(to), true, false) + "m")
		return b.String()
	}
	if from.Fg != to.Fg || from.Bright != to.Bright {
		b.WriteString("\x1b[" + ui.ColorCode(fgOf(to), false, to.Bright) + "m")
	}
	if from.Bg != to.Bg {
		b.WriteString("\x1b[" + ui.ColorCode(bgOf(to), true, false) + "m")
	}
	return b.String()
}

func fgOf(s ui.Style) string {
	if s.Fg == "" {
		return "default"
	}
	return s.Fg
}

func bgOf(s ui.Style) string {
	if s.Bg == "" {
		return "default"
	}
	return s.Bg
}
