// GetStatusFiles parses `git status --porcelain` output.
func (g *GitCommand) GetStatusFiles() ([]StatusFile, error) {
	out, err := g.Run("status", "--untracked-files=all", "--porcelain", "-z", "--find-renames=50%")
	if err != nil {
		return nil, err
	}
	var files []StatusFile
	for _, chunk := range strings.Split(out, "\x00") {
		chunk = strings.TrimSpace(chunk)
		if chunk == "" {
			continue
		}
		lines := strings.Split(chunk, "\n")
		if len(lines) == 0 {
			continue
		}
		first := lines[0]
		if len(first) < 2 {
			continue
		}
		status := first[:2]
		name := first[2:]
		f := StatusFile{ShortStatus: status, Name: name}
		switch status[0] {
		case 'M':
			f.HasUnstagedChanges = true
			f.HasStagedChanges = true
			f.Tracked = true
		case '?':
			f.Tracked = false
		case 'A':
			f.HasStagedChanges = true
			f.Tracked = true
		case 'D':
			f.HasStagedChanges = true
			f.Tracked = true
		}
		switch status[1] {
		case 'M':
			f.HasUnstagedChanges = true
		case 'D':
			f.HasStagedChanges = true
		}
		if len(lines) > 1 && strings.HasPrefix(lines[1], "original ") {
			f.PreviousName = strings.TrimPrefix(lines[1], "original ")
		}
		files = append(files, f)
	}
	return files, nil
}

