// GetCommits returns the commits for the given ref.
func (g *GitCommand) GetCommits(ref string) ([]Commit, error) {
	args := []string{"log", ref, "--topo-order", "--oneline", "--pretty=format:+%H%x00%at%x00%aN%x00%ae%x00%P%x00%m%x00%D%x00%s", "--abbrev=40", "-300", "--no-show-signature", "--"}
	out, err := g.Run(args...)
	if err != nil {
		return nil, err
	}
	return parseCommitLines(out), nil
}

func parseCommitLines(out string) []Commit {
	var commits []Commit
	for _, line := range strings.Split(out, "\n") {
		if line == "" || !strings.HasPrefix(line, "+") {
			continue
		}
		fields := strings.Split(line[1:], "\x00")
		c := Commit{}
		if len(fields) > 0 {
			c.Hash = fields[0]
		}
		if len(fields) > 1 {
			d, e := strconv.ParseInt(fields[1], 10, 64)
			if e == nil {
				c.Date = d
			}
		}
		if len(fields) > 2 {
			c.Author = fields[2]
		}
		if len(fields) > 3 {
			c.AuthorEmail = fields[3]
		}
		if len(fields) > 4 {
			c.Parents = fields[4]
		}
		if len(fields) > 5 {
			c.ReflogMarker = fields[5]
		}
		if len(fields) > 6 {
			c.Action = fields[6]
		}
		if len(fields) > 7 {
			c.Message = fields[7]
		}
		commits = append(commits, c)
	}
	return commits
}

// GetReflogCommits returns the reflog.
func (g *GitCommand) GetReflogCommits() ([]Commit, error) {
	out, err := g.Run("-c", "log.showSignature=false", "log", "-g", "--format=+%H%x00%ct%x00%gs%x00%P")
	if err != nil {
		return nil, err
	}
	var commits []Commit
	for _, line := range strings.Split(out, "\n") {
		if line == "" || !strings.HasPrefix(line, "+") {
			continue
		}
		fields := strings.Split(line[1:], "\x00")
		c := Commit{}
		if len(fields) > 0 {
			c.Hash = fields[0]
		}
		if len(fields) > 1 {
			d, e := strconv.ParseInt(fields[1], 10, 64)
			if e == nil {
				c.Date = d
			}
		}
		if len(fields) > 2 {
			c.Message = fields[2]
		}
		if len(fields) > 3 {
			c.Parents = fields[3]
		}
		commits = append(commits, c)
	}
	return commits, nil
}

// Diff runs a diff between two refs.
func (g *GitCommand) Diff(args ...string) (string, error) {
	full := append([]string{"diff", "--no-ext-diff", "--submodule", "--color=always"}, args...)
	return g.Run(full...)
}

// Show runs `git show` for a commit.
func (g *GitCommand) Show(hash string) (string, error) {
	return g.RunWithOutput("-c", "diff.noprefix=false", "show", "--no-ext-diff", "--submodule", "--color=always", "--unified=3", "--stat", "--decorate", "-p", hash, "--find-renames=50%", "--")
}

// GetDiffFor runs a diff command and returns the output.
func (g *GitCommand) GetDiffFor(files ...string) (string, error) {
	return g.Diff(files...)
}

// WorkingTreeDiff returns the unstaged diff.
func (g *GitCommand) WorkingTreeDiff() (string, error) {
	return g.Diff()
}

// StagedDiff returns the staged diff.
func (g *GitCommand) StagedDiff() (string, error) {
	return g.Diff("--cached")
}
