func (gui *Gui) CurrentSideViewName() string {
	ctx := gui.CurrentContext()
	switch ctx.Window {
	case 0:
		return "status"
	case 1:
		switch ctx.Key {
		case FilesContext:
			return "files"
		case WorktreesContext:
			return "worktrees"
		case SubmodulesContext:
			return "submodules"
		}
	case 2:
		switch ctx.Key {
		case BranchesContext:
			return "branches"
		case RemotesContext:
			return "remotes"
		case TagsContext:
			return "tags"
		}
	case 3:
		switch ctx.Key {
		case CommitsContext:
			return "commits"
		case ReflogContext:
			return "reflog"
		}
	case 4:
		return "stash"
	}
	return "files"
}

// SideViewNames returns the view names of the side panels in order.
func (gui *Gui) SideViewNames() []string {
	return []string{"status", "files", "branches", "commits", "stash"}
}

// SortedKeys returns keys of a map sorted.
func SortedKeys[V any](m map[string]V) []string {
	keys := make([]string, 0, len(m))
	for k := range m {
		keys = append(keys, k)
	}
	sort.Strings(keys)
	return keys
}

// TempDir creates a temporary directory in the lazygit temp dir.
func TempDir() (string, error) {
	base := os.TempDir() + "/lazygit-" + strconv.Itoa(os.Getuid())
	if err := os.MkdirAll(base, 0o700); err != nil {
		return "", err
	}
	dir, err := os.MkdirTemp(base, "lazygit-")
	if err != nil {
		return "", err
	}
	return dir, nil
}

// ErrFatal panics with a wrapped error (for error reporting).
func ErrFatal(err error) {
	if err == nil {
		return
	}
	fmt.Println(err)
	os.Exit(1)
}

