package ui

import (
	"strings"
	"unicode"
)

// KeyType distinguishes key events.
type KeyType int

// Key types.
const (
	KeyRune KeyType = iota
	KeyCtrl
	KeySpecial
)

// Key is a keypress event.
type Key struct {
	Type KeyType
	Rune rune
	Code int
	Alt  bool
}

// Key code constants.
const (
	KeySpace = 32
	KeyEnter = 13
	KeyTab   = 9
	KeyEsc   = 27
	KeyBackspace = 127
)

// ParseKeys decodes a buffer of terminal input into key events.
// It returns the events and the number of bytes consumed.
func ParseKeys(data []byte) ([]Key, int) {
	var keys []Key
	i := 0
	for i < len(data) {
		b := data[i]
		if b == 0x1b {
			// escape sequence
			if i+1 < len(data) && data[i+1] == '[' {
				// CSI
				j := i + 2
				for j < len(data) && (data[j] < 0x40 || data[j] > 0x7e) {
					j++
				}
				if j < len(data) {
					seq := string(data[i+2 : j])
					final := data[j]
					k, ok := parseCSI(seq, final)
					if ok {
						keys = append(keys, k)
						i = j + 1
						continue
					}
				}
				keys = append(keys, Key{Type: KeySpecial, Code: KeyEsc})
				i++
				continue
			}
			if i+1 < len(data) && (data[i+1] == 'O' || data[i+1] == 'o') {
				if i+2 < len(data) {
					k, ok := parseSS3(data[i+2])
					if ok {
						keys = append(keys, k)
						i += 3
						continue
					}
				}
			}
			// alt+key
			if i+2 < len(data) && data[i+1] == 0x1b {
				// double escape
			}
			if i+1 < len(data) && data[i+1] >= 0x20 && data[i+1] < 0x7f {
				r := rune(data[i+1])
				keys = append(keys, Key{Type: KeyRune, Rune: r, Alt: true})
				i += 2
				continue
			}
			keys = append(keys, Key{Type: KeySpecial, Code: KeyEsc})
			i++
			continue
		}
		switch {
		case b == 0:
			i++
		case b == 9:
			keys = append(keys, Key{Type: KeySpecial, Code: KeyTab})
			i++
		case b == 13:
			keys = append(keys, Key{Type: KeySpecial, Code: KeyEnter})
			i++
		case b == 27:
			keys = append(keys, Key{Type: KeySpecial, Code: KeyEsc})
			i++
		case b == 127 || b == 8:
			keys = append(keys, Key{Type: KeySpecial, Code: KeyBackspace})
			i++
		case b < 27 || b == 28 || b == 29 || b == 30 || b == 31:
			// control char
			keys = append(keys, Key{Type: KeyCtrl, Code: int(b)})
			i++
		default:
			// UTF-8
			r, size := decodeRune(data[i:])
			if r == 0 {
				i++
				continue
			}
			keys = append(keys, Key{Type: KeyRune, Rune: r})
			i += size
		}
	}
	return keys, i
}

func decodeRune(b []byte) (rune, int) {
	if len(b) == 0 {
		return 0, 0
	}
	c := b[0]
	switch {
	case c < 0x80:
		return rune(c), 1
	case c&0xe0 == 0xc0 && len(b) >= 2:
		return rune(c&0x1f)<<6 | rune(b[1]&0x3f), 2
	case c&0xf0 == 0xe0 && len(b) >= 3:
		return rune(c&0x0f)<<12 | rune(b[1]&0x3f)<<6 | rune(b[2]&0x3f), 3
	case c&0xf8 == 0xf0 && len(b) >= 4:
		return rune(c&0x07)<<18 | rune(b[1]&0x3f)<<12 | rune(b[2]&0x3f)<<6 | rune(b[3]&0x3f), 4
	}
	return 0, 0
}

func parseCSI(seq string, final byte) (Key, bool) {
	mods := 0
	params := seq
	// xterm modifier encoding: 1;5C
	if idx := strings.IndexByte(seq, ';'); idx >= 0 {
		params = seq[:idx]
		if n, err := atoi(seq[idx+1:]); err == nil {
			mods = n
		}
	}
	var name string
	switch final {
	case 'A':
		name = "up"
	case 'B':
		name = "down"
	case 'C':
		name = "right"
	case 'D':
		name = "left"
	case 'H':
		name = "home"
	case 'F':
		name = "end"
	case 'Z':
		return Key{Type: KeySpecial, Code: codeFor("backtab")}, true
	case 'P':
		name = "f1"
	case 'Q':
		name = "f2"
	case 'R':
		name = "f3"
	case 'S':
		name = "f4"
	case '~':
		switch params {
		case "1", "7":
			name = "home"
		case "2":
			name = "insert"
		case "3":
			name = "del"
		case "4", "8":
			name = "end"
		case "5":
			name = "pgup"
		case "6":
			name = "pgdown"
		case "11":
			name = "f1"
		case "12":
			name = "f2"
		case "13":
			name = "f3"
		case "14":
			name = "f4"
		case "15":
			name = "f5"
		case "17":
			name = "f6"
		case "18":
			name = "f7"
		case "19":
			name = "f8"
		case "20":
			name = "f9"
		case "21":
			name = "f10"
		case "23":
			name = "f11"
		case "24":
			name = "f12"
		default:
			return Key{}, false
		}
	default:
		return Key{}, false
	}
	if mods >= 2 {
		switch mods {
		case 2:
			name = "s-" + name
		case 5:
			return Key{Type: KeySpecial, Code: codeFor("c-" + name)}, true
		case 6:
			name = "s-" + name
		}
	}
	return Key{Type: KeySpecial, Code: codeFor(name)}, true
}

func parseSS3(c byte) (Key, bool) {
	switch c {
	case 'A':
		return Key{Type: KeySpecial, Code: codeFor("up")}, true
	case 'B':
		return Key{Type: KeySpecial, Code: codeFor("down")}, true
	case 'C':
		return Key{Type: KeySpecial, Code: codeFor("right")}, true
	case 'D':
		return Key{Type: KeySpecial, Code: codeFor("left")}, true
	case 'H':
		return Key{Type: KeySpecial, Code: codeFor("home")}, true
	case 'F':
		return Key{Type: KeySpecial, Code: codeFor("end")}, true
	case 'P':
		return Key{Type: KeySpecial, Code: codeFor("f1")}, true
	}
	return Key{}, false
}

var specialCodes = map[string]int{}

func atoi(s string) (int, error) {
	n := 0
	for _, c := range s {
		if c < '0' || c > '9' {
			return 0, errAtoi
		}
		n = n*10 + int(c-'0')
	}
	return n, nil
}

type atoiErr struct{}

func (atoiErr) Error() string { return "atoi" }

var errAtoi = atoiErr{}

func codeFor(name string) int {
	codes := map[string]int{
		"up": 1000, "down": 1001, "right": 1002, "left": 1003,
		"home": 1004, "end": 1005, "pgup": 1006, "pgdown": 1007,
		"insert": 1008, "del": 1009, "f1": 1010, "f2": 1011, "f3": 1012,
		"f4": 1013, "f5": 1014, "f6": 1015, "f7": 1016, "f8": 1017,
		"f9": 1018, "f10": 1019, "f11": 1020, "f12": 1021,
		"space": KeySpace, "enter": KeyEnter, "tab": KeyTab,
		"backtab": 1030, "esc": KeyEsc, "backspace": KeyBackspace,
	}
	if n, ok := codes[name]; ok {
		return n
	}
	// control keys
	if strings.HasPrefix(name, "c-") {
		c := name[2:]
		if len(c) == 1 {
			ch := c[0]
			if ch >= 'a' && ch <= 'z' {
				return int(ch-'a') + 1
			}
			if ch >= '@' && ch <= '_' {
				return int(ch - '@')
			}
		}
		// ctrl+arrow
		if idx, ok := codes[c]; ok {
			return idx + 200
		}
	}
	if strings.HasPrefix(name, "a-") {
		c := name[2:]
		if idx, ok := codes[c]; ok {
			return idx + 300
		}
		if len(c) == 1 {
			return 300 + int(c[0])
		}
	}
	if strings.HasPrefix(name, "s-") {
		c := name[2:]
		if idx, ok := codes[c]; ok {
			return idx + 400
		}
	}
	return 0
}

// NameForKey returns the gocui-style name of a key event.
func NameForKey(k Key) string {
	names := map[int]string{
		1000: "up", 1001: "down", 1002: "right", 1003: "left",
		1004: "home", 1005: "end", 1006: "pgup", 1007: "pgdown",
		1008: "insert", 1009: "del", 1010: "f1", 1011: "f2", 1012: "f3",
		1013: "f4", 1014: "f5", 1015: "f6", 1016: "f7", 1017: "f8",
		1018: "f9", 1019: "f10", 1020: "f11", 1021: "f12",
		KeySpace: "space", KeyEnter: "enter", KeyTab: "tab",
		1030: "backtab", KeyEsc: "esc", KeyBackspace: "backspace",
	}
	if k.Type == KeyRune {
		if unicode.IsPrint(k.Rune) {
			return string(k.Rune)
		}
		return ""
	}
	if k.Type == KeyCtrl {
		if k.Code >= 1 && k.Code <= 26 {
			return "<c-" + string(rune('a'+k.Code-1)) + ">"
		}
		if k.Code >= 27 && k.Code <= 31 {
			return "<c-" + string(rune('4'+k.Code-27)) + ">"
		}
		return ""
	}
	if k.Alt {
		if n, ok := names[k.Code-300]; ok {
			return "<a-" + n + ">"
		}
		if k.Code >= 300+32 && k.Code < 300+127 {
			return "<a-" + string(rune(k.Code-300)) + ">"
		}
		return ""
	}
	if k.Code >= 1000 && k.Code < 1030 {
		if n, ok := names[k.Code]; ok {
			return "<" + n + ">"
		}
	}
	if k.Code >= 1100 && k.Code < 1130 {
		if n, ok := names[k.Code-200]; ok {
			return "<c-" + n + ">"
		}
	}
	if k.Code >= 1400 && k.Code < 1430 {
		if n, ok := names[k.Code-400]; ok {
			return "<s-" + n + ">"
		}
	}
	if k.Code >= 1300 && k.Code < 1330 {
		if n, ok := names[k.Code-300]; ok {
			return "<a-" + n + ">"
		}
	}
	if n, ok := names[k.Code]; ok {
		return "<" + n + ">"
	}
	return ""
}
