package gui

import (
	"math"

	"github.com/jesseduffield/lazygit/pkg/ui"
)

// Layout holds the computed geometry of the app.
type Layout struct {
	SideWidth  int
	MainWidth  int
	Sections   []int // status, files, branches, commits, stash
	MainHeight int
	CmdLogHeight int
	ShowSide   bool
	ShowMain   bool
}

// viewHeight returns the height available for views (excluding the bottom line).
func (gui *Gui) viewHeight() int {
	h := gui.Height
	if gui.Config.Gui.ShowBottomLine {
		h--
	}
	return h
}

// ComputeLayout calculates the layout for the current terminal size.
func (gui *Gui) ComputeLayout() *Layout {
	l := &Layout{}
	w := gui.Width
	h := gui.viewHeight()
	if w <= 0 || h <= 0 {
		return l
	}
	sideWidth := int(math.Ceil(float64(w) * gui.Config.Gui.SidePanelWidth))
	if sideWidth >= w {
		l.ShowSide = true
		l.ShowMain = false
		l.SideWidth = w
	} else if sideWidth <= 0 {
		l.ShowSide = false
		l.ShowMain = true
		l.SideWidth = 0
	} else {
		l.ShowSide = true
		l.ShowMain = true
		l.SideWidth = sideWidth
	}
	l.MainWidth = w - l.SideWidth

	// command log
	cmdLogHeight := 0
	if gui.Config.Gui.ShowCommandLog && !gui.AppState.HideCommandLog {
		if gui.Height >= 40 {
			cmdLogHeight = gui.Config.Gui.CommandLogSize + 2
		} else {
			cmdLogHeight = 3
		}
		if cmdLogHeight > h {
			cmdLogHeight = h
		}
	}
	l.CmdLogHeight = cmdLogHeight
	if cmdLogHeight > 0 {
		l.MainHeight = h - cmdLogHeight
	} else {
		l.MainHeight = h
	}

	// side panel sections
	sections := gui.sidePanelSectionHeights(h)
	l.Sections = sections
	return l
}

func (gui *Gui) focusedWindow() int {
	ctx := gui.CurrentContext()
	if ctx.Window >= 0 {
		return ctx.Window
	}
	// fall back to the last focused side window
	if gui.lastFocusedWindow >= 0 {
		return gui.lastFocusedWindow
	}
	return 1
}

// sidePanelSectionHeights returns the heights of status, files, branches,
// commits and stash.
func (gui *Gui) sidePanelSectionHeights(viewHeight int) []int {
	sections := []int{1, 1, 1, 1, 1}
	if viewHeight <= 0 {
		return sections
	}
	if viewHeight <= 20 {
		min := 1
		return gui.distribute(sections, viewHeight, min, 1)
	}
	if viewHeight <= 27 {
		min := 3
		return gui.distribute(sections, viewHeight, min, 0)
	}
	// equal distribution between files, branches and commits
	status, stash := 3, 3
	rem := viewHeight - status - stash
	base := rem / 3
	extra := rem % 3
	files := base
	branches := base
	commits := base
	if extra > 0 {
		files++
	}
	if extra > 1 {
		branches++
	}
	return []int{status, files, branches, commits, stash}
}

// distribute gives every section the minimum height and the remainder to the
// focused section.
func (gui *Gui) distribute(sections []int, viewHeight, min, minAfter int) []int {
	out := make([]int, len(sections))
	for i := range out {
		if i < minAfter {
			out[i] = min
		} else {
			out[i] = min
		}
	}
	// the first two sections (status, stash) and the non-focused ones keep min
	focused := gui.focusedWindow()
	total := 0
	for i := range out {
		if i != focused {
			total += min
		}
	}
	rem := viewHeight - total
	if rem < min {
		rem = min
	}
	if focused >= 0 && focused < len(out) {
		out[focused] = rem
	}
	return out
}

// Box drawing characters for each border style.
type boxChars struct {
	TopLeft, TopRight, BottomLeft, BottomRight, Horizontal, Vertical rune
	SingleTopLeft, SingleTopRight rune
}

func borderChars(style string) boxChars {
	switch style {
	case "single":
		return boxChars{'\u250c', '\u2510', '\u2514', '\u2518', '\u2500', '\u2502', '\u2576', '\u2574'}
	case "double":
		return boxChars{'\u2554', '\u2557', '\u255a', '\u255d', '\u2550', '\u2551', '\u2554', '\u2557'}
	case "heavy":
		return boxChars{'\u250f', '\u2513', '\u2517', '\u251b', '\u2501', '\u2503', '\u250f', '\u2513'}
	default: // rounded
		return boxChars{'\u256d', '\u256e', '\u2570', '\u256f', '\u2500', '\u2502', '\u2576', '\u2574'}
	}
}

// borderStyle returns the style for a view's border.
func (gui *Gui) borderStyle(focused bool) ui.Style {
	parts := gui.Config.Gui.Theme.InactiveBorderColor
	if focused {
		parts = gui.Config.Gui.Theme.ActiveBorderColor
	}
	if gui.Searching && focused {
		parts = gui.Config.Gui.Theme.SearchingActiveBorderColor
	}
	return ui.ParseStyle(parts)
}

// selectedStyle returns the style for the selected line of a view.
func (gui *Gui) selectedStyle(focused bool) ui.Style {
	if focused {
		return ui.ParseStyle([]string{"default", gui.Config.Gui.Theme.SelectedLineBgColor[0]})
	}
	return ui.ParseStyle(gui.Config.Gui.Theme.InactiveViewSelectedLineBgColor)
}

