package gui

import (
	"strings"

	"github.com/jesseduffield/lazygit/pkg/ui"
)

// titleRuns builds the runs for a view's title (excluding the corners).
func (gui *Gui) titleRuns(v *View) []ui.Run {
	bs := v.BorderStyle
	runs := []ui.Run{}
	// horizontal + jump key + horizontal
	if v.JumpKey != "" {
		runs = append(runs, ui.Run{Text: "\u2500[" + v.JumpKey + "]\u2500", Style: bs})
	} else {
		runs = append(runs, ui.Run{Text: "\u2500", Style: bs})
	}
	if len(v.Tabs) > 0 {
		for i, tab := range v.Tabs {
			active := i == v.ActiveTab
			style := ui.Style{Fg: "green"}
			if active && v.Focused {
				style = bs
			}
			text := tab.Name
			if i < len(v.Tabs)-1 {
				text += " "
			}
			runs = append(runs, ui.Run{Text: text, Style: style})
			if i < len(v.Tabs)-1 {
				sep := "-"
				if i+1 == v.ActiveTab {
					// the separator before the active tab stays default
					runs = append(runs, ui.Run{Text: sep + " ", Style: ui.Style{Fg: "default"}})
				} else {
					runs = append(runs, ui.Run{Text: sep + " ", Style: ui.Style{Fg: "default"}})
				}
			}
		}
	} else if v.Title != "" {
		runs = append(runs, ui.Run{Text: v.Title, Style: ui.Style{Fg: "default"}})
	}
	return runs
}

// renderView renders a view into the screen.
func (gui *Gui) renderView(s *Screen, v *View) {
	if !v.Visible || v.W <= 0 || v.H <= 0 {
		return
	}
	chars := borderChars(gui.Config.Gui.Border)
	bs := v.BorderStyle
	innerW := v.InnerWidth()
	innerH := v.InnerHeight()

	if v.H == 1 {
		// single line frame
		s.SetCell(v.X, v.Y, chars.SingleTopLeft, bs)
		col := v.X + 1
		used := 1
		for _, r := range gui.titleRuns(v) {
			w := runeLen(r.Text)
			if used+w > v.W-1 {
				break
			}
			s.SetText(col, v.Y, w, r.Text, r.Style)
			col += w
			used += w
		}
		for col < v.X+v.W-1 {
			s.SetCell(col, v.Y, chars.Horizontal, bs)
			col++
		}
		if v.W > 1 {
			s.SetCell(v.X+v.W-1, v.Y, chars.SingleTopRight, bs)
		}
		return
	}

	// top border
	s.SetCell(v.X, v.Y, chars.TopLeft, bs)
	col := v.X + 1
	used := 1
	for _, r := range gui.titleRuns(v) {
		w := runeLen(r.Text)
		if used+w > v.W-1 {
			break
		}
		s.SetText(col, v.Y, w, r.Text, r.Style)
		col += w
		used += w
	}
	for col < v.X+v.W-1 {
		s.SetCell(col, v.Y, chars.Horizontal, bs)
		col++
	}
	s.SetCell(v.X+v.W-1, v.Y, chars.TopRight, bs)

	// bottom border
	bottomY := v.Y + v.H - 1
	s.SetCell(v.X, bottomY, chars.BottomLeft, bs)
	for c := v.X + 1; c < v.X+v.W-1; c++ {
		s.SetCell(c, bottomY, chars.Horizontal, bs)
	}
	s.SetCell(v.X+v.W-1, bottomY, chars.BottomRight, bs)
	if v.Footer != "" {
		text := v.Footer
		w := runeLen(text)
		start := v.X + v.W - 2 - w
		s.SetText(start, bottomY, w, text, ui.Style{Fg: "default"})
	}

	// content
	lines := v.ContentLines()
	if innerH <= 0 || innerW <= 0 {
		return
	}
	if v.ScrollTop > len(lines)-innerH {
		v.ScrollTop = len(lines) - innerH
	}
	if v.ScrollTop < 0 {
		v.ScrollTop = 0
	}
	for i := 0; i < innerH; i++ {
		idx := v.ScrollTop + i
		y := v.Y + 1 + i
		selStyle := ui.DefaultStyle
		isSelected := idx == v.Selected && idx >= 0 && idx < len(lines)
		if isSelected {
			selStyle = v.SelectedStyle
			if !v.Focused {
				selStyle = v.InactiveSelectedStyle
			}
		}
		if idx < len(lines) {
			gui.renderLine(s, v, v.X+1, y, innerW, lines[idx], selStyle, isSelected)
		} else {
			gui.renderLine(s, v, v.X+1, y, innerW, Line{}, selStyle, isSelected)
		}
	}
	// scrollbar
	if v.ShowScrollbar {
		gui.renderScrollbar(s, v)
	}
}

// renderLine renders a line with padding.
func (gui *Gui) renderLine(s *Screen, v *View, x, y, w int, line Line, selStyle ui.Style, selected bool) {
	base := ui.Style{Fg: "default", Bg: "default"}
	if selected {
		base = selStyle
	}
	col := x
	end := x + w
	for _, r := range line.Runs {
		st := r.Style
		if selected {
			// brighten fg colors on the selected line
			if st.Fg != "" && st.Fg != "default" && ui.IsBrightable(st.Fg) {
				st = st.WithBright()
			}
			if st.Bg == "" || st.Bg == "default" {
				st.Bg = selStyle.Bg
			}
			if st.Fg == "" {
				st.Fg = selStyle.Fg
			}
			if selStyle.Bold && !st.Bold {
				st.Bold = true
			}
		}
		for _, ch := range r.Text {
			if col >= end {
				break
			}
			s.SetCell(col, y, ch, st)
			col++
		}
		if col >= end {
			break
		}
	}
	// padding
	for c := col; c < end; c++ {
		s.SetCell(c, y, ' ', base)
	}
}

// renderScrollbar draws the scrollbar of a view.
func (gui *Gui) renderScrollbar(s *Screen, v *View) {
	lines := len(v.ContentLines())
	inner := v.InnerHeight()
	if lines <= inner || inner <= 0 {
		return
	}
	thumb := 1
	if v.Kind == "main" {
		h := v.H - 1
		c := lines
		if c+h-1 > 0 {
			thumb = int(float64(h*h)/float64(c+h-1) + 0.4)
		}
	} else {
		thumb = int(float64(inner*inner)/float64(lines) + 0.5)
	}
	if thumb < 1 {
		thumb = 1
	}
	if thumb > inner {
		thumb = inner
	}
	scrollRange := lines - inner
	if scrollRange <= 0 {
		scrollRange = 1
	}
	start := v.ScrollTop * (inner - thumb) / scrollRange
	if v.ScrollTop >= scrollRange {
		start = inner - thumb
	}
	x := v.X + v.W - 1
	for i := 0; i < thumb; i++ {
		y := v.Y + 1 + start + i
		if y > v.Y+v.H-2 {
			break
		}
		s.SetCell(x, y, '\u2590', ui.DefaultStyle)
	}
}

// Kind distinguishes main views from list views (for scrollbar maths).
// Kind is set on the view when it is created.

func runeLen(s string) int {
	n := 0
	for range s {
		n++
	}
	return n
}

