// branchByName finds a branch by name.
func (gui *Gui) branchByName(name string) *commands.Branch {
	for i := range gui.Branches {
		if gui.Branches[i].Name == name {
			return &gui.Branches[i]
		}
	}
	return nil
}

// trackSymbol converts a git track string into a symbol.
func (gui *Gui) trackSymbol(track string) string {
	track = strings.TrimSpace(track)
	if track == "" {
		return ""
	}
	if track == "[gone]" {
		return "\u2717"
	}
	ahead, behind := 0, 0
	for _, part := range strings.Split(strings.Trim(track, "[]"), ",") {
		part = strings.TrimSpace(part)
		if strings.HasPrefix(part, "ahead") {
			n, _ := strconv.Atoi(strings.TrimSpace(strings.TrimPrefix(part, "ahead")))
			ahead = n
		} else if strings.HasPrefix(part, "behind") {
			n, _ := strconv.Atoi(strings.TrimSpace(strings.TrimPrefix(part, "behind")))
			behind = n
		}
	}
	if ahead > 0 && behind > 0 {
		return "\u21c5" + strconv.Itoa(ahead)
	}
	if ahead > 0 {
		return "\u2191" + strconv.Itoa(ahead)
	}
	if behind > 0 {
		return "\u2193" + strconv.Itoa(behind)
	}
	return "\u2713"
}

// fileTreeLines builds the file tree.
func (gui *Gui) fileTreeLines() []Line {
	files := gui.StatusFiles
	sort.SliceStable(files, func(i, j int) bool {
		return files[i].Name < files[j].Name
	})
	gui.StatusFiles = files
	if !gui.Config.Gui.ShowFileTree {
		// flat list
		var lines []Line
		for _, f := range gui.StatusFiles {
			lines = append(lines, gui.fileLine(f.Name, 0, f))
		}
		return lines
	}
	type node struct {
		name     string
		path     string
		isDir    bool
		children []*node
		expanded bool
		file     *commands.StatusFile
	}
	root := &node{name: "/", path: "", isDir: true, expanded: true}
	index := map[string]*node{"/": root}
	for i := range gui.StatusFiles {
		f := gui.StatusFiles[i]
		parts := strings.Split(f.Name, "/")
		cur := root
		path := ""
		for i, p := range parts {
			last := i == len(parts)-1
			if path == "" {
				path = p
			} else {
				path = path + "/" + p
			}
			key := path
			if last {
				child := &node{name: p, path: path, isDir: false, file: &gui.StatusFiles[i]}
				cur.children = append(cur.children, child)
			} else {
				n, ok := index[key]
				if !ok {
					n = &node{name: p, path: path, isDir: true, expanded: true}
					index[key] = n
					cur.children = append(cur.children, n)
				}
				cur = n
			}
		}
	}
	// sort children: directories first, then files, alphabetically
	var sortNodes func(n *node)
	sortNodes = func(n *node) {
		sort.SliceStable(n.children, func(i, j int) bool {
			a, b := n.children[i], n.children[j]
			if a.isDir != b.isDir {
				return a.isDir
			}
			return a.name < b.name
		})
		for _, c := range n.children {
			sortNodes(c)
		}
	}
	sortNodes(root)

	var lines []Line
	var walk func(n *node, depth int, path string)
	walk = func(n *node, depth int, path string) {
		if n.isDir {
			marker := "\u25bc"
			if !n.expanded {
				marker = "\u25b6"
			}
			prefix := strings.Repeat(" ", depth*2)
			runs := []ui.Run{{Text: prefix + marker, Style: ui.Style{Fg: "default"}}}
			if len(path) == 0 {
				runs = append(runs, ui.Run{Text: " /", Style: ui.Style{Fg: "default"}})
			} else {
				runs = append(runs, ui.Run{Text: " "+path, Style: ui.Style{Fg: "default"}})
			}
			lines = append(lines, Line{Runs: runs})
			if n.expanded {
				for _, c := range n.children {
					walk(c, depth+1, c.path)
				}
			}
		} else {
			lines = append(lines, gui.fileLine(n.file.Name, depth, n.file))
		}
	}
	if gui.Config.Gui.ShowRootItemInFileTree {
		walk(root, 0, "")
	} else {
		for _, c := range root.children {
			walk(c, 0, c.path)
		}
	}
	return lines
}

// fileLine renders a single file line.
func (gui *Gui) fileLine(name string, depth int, f *commands.StatusFile) Line {
	prefix := strings.Repeat(" ", depth*2)
	marker := ""
	style := ui.Style{Fg: "default"}
	short := f.ShortStatus
	switch {
	case strings.HasPrefix(short, "??"):
		marker = "??"
		style = ui.Style{Fg: "red"}
	case strings.HasPrefix(short, "M"):
		marker = "M"
		style = ui.Style{Fg: "red"}
	case strings.HasPrefix(short, "A"):
		marker = "A"
		style = ui.Style{Fg: "green"}
	case strings.HasPrefix(short, "D"):
		marker = "D"
		style = ui.Style{Fg: "red"}
	case strings.HasPrefix(short, "R"):
		marker = "R"
		style = ui.Style{Fg: "yellow"}
	case strings.HasPrefix(short, "C"):
		marker = "C"
		style = ui.Style{Fg: "cyan"}
	}
	if len(marker) < 2 {
		marker = strings.Repeat(" ", 2-len(marker)) + marker
	}
	return Line{Runs: []ui.Run{
		{Text: prefix + marker + " ", Style: ui.Style{Fg: "default"}},
		{Text: name, Style: style},
	}}
}

