func (gui *Gui) branchLines() []Line {
	var lines []Line
	for i := range gui.Branches {
		b := &gui.Branches[i]
		recency := ""
		if !b.Head {
			recency = gui.recency(b.CommitDate)
		}
		if len(recency) < 2 {
			recency = strings.Repeat(" ", 2-len(recency)) + recency
		}
		marker := " "
		markerStyle := ui.Style{Fg: "default"}
		if b.Head {
			marker = "*"
			markerStyle = ui.Style{Fg: "green"}
		}
		runs := []ui.Run{{Text: recency, Style: ui.Style{Fg: "cyan"}}, {Text: marker, Style: markerStyle}, {Text: " " + b.Name, Style: ui.Style{Fg: "default"}}}
		if track := gui.trackSymbol(b.Pullables); track != "" {
			runs = append(runs, ui.Run{Text: " " + track, Style: ui.Style{Fg: "default"}})
		}
		lines = append(lines, Line{Runs: runs})
	}
