func (gui *Gui) commitLine(c *commands.Commit, reflog bool) Line {
	runs := []ui.Run{}
	hash := c.Hash
	if len(hash) > gui.Config.Gui.CommitHashLength {
		hash = hash[:gui.Config.Gui.CommitHashLength]
	}
	runs = append(runs, ui.Run{Text: hash, Style: ui.Style{Fg: "green"}})
	author := c.Author
	shortLen := gui.Config.Gui.CommitAuthorShortLength
	longLen := gui.Config.Gui.CommitAuthorLongLength
	if len(author) > shortLen {
		author = author[:shortLen]
	}
	runs = append(runs, ui.Run{Text: " " + author, Style: ui.Style{Fg: gui.authorColor(c.Author)}})
	marker := "\u25ef"
	if gui.commitPushed(c.Hash) {
		marker = "\u25cf"
	}
	markerStyle := ui.Style{Fg: "default"}
	if gui.Config.Gui.StatusPanelView != "basic" {
	}
	runs = append(runs, ui.Run{Text: " " + marker, Style: markerStyle})
	if !reflog {
		for _, t := range gui.tagsForCommit(c.Hash) {
			runs = append(runs, ui.Run{Text: " " + t, Style: ui.Style{Fg: "magenta", Bold: true}})
		}
	}
	msg := c.Message
	if gui.Config.Gui.CommitLength.Show {
	}
	runs = append(runs, ui.Run{Text: " " + msg, Style: ui.Style{Fg: "default"}})
	return Line{Runs: runs}
}

// tagsForCommit returns the tags that point to a commit.
func (gui *Gui) tagsForCommit(hash string) []string {
	var tags []string
	full := hash
	for i := range gui.Tags {
		t := gui.Tags[i]
		if len(t.CommitHash) >= len(full) && t.CommitHash[:len(full)] == full {
			tags = append(tags, t.Name)
		}
	}
	return tags
}

