	runs = append(runs, ui.Run{Text: hash, Style: ui.Style{Fg: "green"}})
	author := c.Author
	shortLen := gui.Config.Gui.CommitAuthorShortLength
	longLen := gui.Config.Gui.CommitAuthorLongLength
