// tagsForCommit returns the tags that point to a commit.
func (gui *Gui) tagsForCommit(hash string) []string {
	var tags []string
	full := hash
	for i := range gui.Tags {
		t := gui.Tags[i]
		if len(t.CommitHash) >= len(full) && t.CommitHash[:len(full)] == full {
			tags = append(tags, t.Name)
		}
	}
	return tags
}

// commitPushed reports whether a commit is on the upstream.
func (gui *Gui) commitPushed(hash string) bool {
	return false
}

// reflogLines builds the reflog panel content.
func (gui *Gui) reflogLines() []Line {
	var lines []Line
	for i := range gui.ReflogCommits {
		c := &gui.ReflogCommits[i]
		runs := []ui.Run{}
		hash := c.Hash
		if len(hash) > gui.Config.Gui.CommitHashLength {
			hash = hash[:gui.Config.Gui.CommitHashLength]
		}
		runs = append(runs, ui.Run{Text: hash, Style: ui.Style{Fg: "green"}})
		runs = append(runs, ui.Run{Text: " " + c.Message, Style: ui.Style{Fg: "default"}})
		lines = append(lines, Line{Runs: runs})
	}
	return lines
}

// stashLines builds the stash panel content.
func (gui *Gui) stashLines() []Line {
	var lines []Line
	for i := range gui.StashEntries {
		e := &gui.StashEntries[i]
		runs := []ui.Run{{Text: gui.recency(e.CreationDate), Style: ui.Style{Fg: "cyan"}}, {Text: " " + e.Description, Style: ui.Style{Fg: "default"}}}
		lines = append(lines, Line{Runs: runs})
	}
	return lines
}

// remoteLines builds the remotes panel content.
func (gui *Gui) remoteLines() []Line {
	var lines []Line
	for _, r := range gui.RemoteNames {
		n := 0
		for i := range gui.RemoteBranches {
			if strings.HasPrefix(gui.RemoteBranches[i].Name, r+"/") {
				n++
			}
		}
		lines = append(lines, NewLine(fmt.Sprintf("%s %d branches", r, n)))
	}
	return lines
}

// tagLines builds the tags panel content.
func (gui *Gui) tagLines() []Line {
	var lines []Line
	for i := range gui.Tags {
		t := gui.Tags[i]
		runs := []ui.Run{{Text: t.Name, Style: ui.Style{Fg: "default"}}}
		if t.Message != "" {
			runs = append(runs, ui.Run{Text: " " + t.Message, Style: ui.Style{Fg: "default"}})
		}
		lines = append(lines, Line{Runs: runs})
	}
	return lines
}

// worktreeLines builds the worktrees panel content.
func (gui *Gui) worktreeLines() []Line {
	var lines []Line
	for i := range gui.Worktrees {
		w := &gui.Worktrees[i]
		marker := " "
		style := ui.Style{Fg: "default"}
		if w.Current {
			marker = "*"
			style = ui.Style{Fg: "green"}
		}
		text := "  " + marker + " " + w.Name() + " (" + w.Branch + ")"
		lines = append(lines, Line{Runs: []ui.Run{{Text: text, Style: style}}})
	}
	return lines
}

// submoduleLines builds the submodules panel content.
func (gui *Gui) submoduleLines() []Line {
	var lines []Line
	for i := range gui.Submodules {
		lines = append(lines, NewLine(gui.Submodules[i].Name))
	}
	return lines
}

// authorColor returns the color for an author name.
func (gui *Gui) authorColor(name string) string {
	if c, ok := gui.Config.Gui.AuthorColors[name]; ok {
		return c
	}
	return authorHashColor(name)
}

