d2=json.load(open('/tmp/aa.json'))
d2={k:(11 if '93' in v else int(v.split(';')[-1])) for k,v in d2.items()}
d1={'A':10,'B':127,'C':178,'D':124,'E':125,'F':130,'G':92,'H':20,'I':221,'J':148,'K':63,'L':198,'M':26,'N':57,'O':119,'P':41,'Q':162,'R':56,'S':38,'T':163,'U':41,'V':170,'W':77,'X':68,'Y':215,'Z':166}
data={**d1,**d2}
def fnv1a(b):
    h=2166136261
    for c in b: h^=c; h=(h*16777619)&0xffffffff
    return h
def fnv1(b):
    h=2166136261
    for c in b: h=(h*16777619)&0xffffffff; h^=c
    return h
def to256(r,g,b):
    # standard: cube index if all components > 0x00 and < 0xff else basic/gray
    def comp(v):
        if v<48: return 0
        if v<115: return 1
        if v<155: return 2
        if v<195: return 3
        if v<235: return 4
        return 5
    cr,cg,cb=comp(r),comp(g),comp(b)
    if cr==cg==cb:
        gray=8+ (cr if cr>0 else 0)
        # gray scale: 232 + i for i in 0..23
        return 232+max(0,min(23,round((r-8)/10))) if 0 else 232
    return 16+36*cr+6*cg+cb
best=[]
for hn,hf in [('fnv1a',fnv1a),('fnv1',fnv1),('sum',lambda b: sum(b)),('crc',None)]:
  for s10 in range(1,11):
    for l10 in range(2,9):
      ok=0
      for k,v in data.items():
        h=(hf(k.encode())%3600)/3600.0
        r,g,b=colorsys.hls_to_rgb(h, l10/10.0, s10/10.0)
        idx=to256(int(r*255),int(g*255),int(b*255))
        if idx==v: ok+=1
      best.append((ok,hn,s10,l10))
best.sort(reverse=True); print(best[:6])
