// Refresh runs the git commands to update the repo state.
func (gui *Gui) Refresh() {
	if gui.Git == nil {
		return
	}
	if branches, err := gui.Git.GetBranches(); err == nil {
		gui.Branches = branches
		for i := range gui.Branches {
			if gui.Branches[i].Head {
				gui.CurrentBranch = gui.Branches[i].Name
			}
		}
	}
	if names, err := gui.Git.GetRemotes(); err == nil {
		gui.RemoteNames = names
	}
	if tags, err := gui.Git.GetTags(); err == nil {
		gui.Tags = tags
	}
	if stash, err := gui.Git.GetStashEntries(); err == nil {
		gui.StashEntries = stash
	}
	if files, err := gui.Git.GetStatusFiles(); err == nil {
		gui.StatusFiles = files
	}
	if wts, err := gui.Git.GetWorktrees(); err == nil {
		gui.Worktrees = wts
		for i := range gui.Worktrees {
			wt := &gui.Worktrees[i]
			wt.Name = filepath.Base(wt.Path)
			if wt.Path == gui.RepoPath {
				wt.Current = true
			}
		}
	}
	if subs, err := gui.getSubmodules(); err == nil {
		gui.Submodules = subs
	}
	if commits, err := gui.Git.GetCommits("HEAD"); err == nil {
		gui.Commits = commits
	}
	if reflog, err := gui.Git.GetReflogCommits(); err == nil {
		gui.ReflogCommits = reflog
	}
	if remoteBranches, err := gui.getRemoteBranches(); err == nil {
		gui.RemoteBranches = remoteBranches
	}
	gui.MainBranches = gui.Config.Git.MainBranches
}

func (gui *Gui) getSubmodules() ([]Submodule, error) {
	out, err := gui.Git.Run("submodule", "status", "--recursive")
	if err != nil {
		return nil, err
	}
	var subs []Submodule
	for _, line := range strings.Split(out, "\n") {
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 3 {
			continue
		}
		sub := Submodule{Name: fields[2], Path: fields[1], Hash: fields[0]}
		subs = append(subs, sub)
	}
	return subs, nil
}

func (gui *Gui) getRemoteBranches() ([]commands.Branch, error) {
	out, err := gui.Git.Run("for-each-ref", "--sort=-committerdate", "--format="+commands.RemoteBranchFormat, "refs/remotes")
	if err != nil {
		return nil, err
	}
	var branches []commands.Branch
	for _, line := range strings.Split(out, "\n") {
		if line == "" {
			continue
		}
		fields := strings.Split(line, "\x00")
		b := commands.Branch{}
		if len(fields) > 0 {
			b.Name = strings.TrimPrefix(fields[0], "refs/remotes/")
		}
		if len(fields) > 1 {
			b.Subject = fields[1]
		}
		if len(fields) > 2 {
			d, e := strconv.ParseInt(fields[2], 10, 64)
			if e == nil {
				b.CommitDate = d
			}
		}
		branches = append(branches, b)
	}
	return branches, nil
}

