}

func (gui *Gui) getSubmodules() ([]Submodule, error) {
	out, err := gui.Git.Run("submodule", "status", "--recursive")
	if err != nil {
		return nil, err
	}
	var subs []Submodule
	for _, line := range strings.Split(out, "\n") {
		if line == "" {
			continue
		}
		fields := strings.Fields(line)
		if len(fields) < 3 {
			continue
		}
		sub := Submodule{Name: fields[2], Path: fields[1], Hash: fields[0]}
		subs = append(subs, sub)
	}
	return subs, nil
}

func (gui *Gui) getRemoteBranches() ([]commands.Branch, error) {
	out, err := gui.Git.Run("for-each-ref", "--sort=-committerdate", "--format="+commands.RemoteBranchFormat, "refs/remotes")
	if err != nil {
		return nil, err
	}
	var branches []commands.Branch
	for _, line := range strings.Split(out, "\n") {
		if line == "" {
			continue
		}
		fields := strings.Split(line, "\x00")
		b := commands.Branch{}
		if len(fields) > 0 {
			b.Name = strings.TrimPrefix(fields[0], "refs/remotes/")
		}
		if len(fields) > 1 {
			b.Subject = fields[1]
		}
		if len(fields) > 2 {
			d, e := strconv.ParseInt(fields[2], 10, 64)
			if e == nil {
				b.CommitDate = d
			}
		}
		branches = append(branches, b)
	}
	return branches, nil
}

