// authorHashColor computes a pseudo-random color for an author name.
func authorHashColor(name string) string {
	if name == "" {
		return "default"
	}
	h := uint32(2166136261)
	for i := 0; i < len(name); i++ {
		h ^= uint32(name[i])
		h *= 16777619
	}
	return strconv.Itoa(int(h % 256))
