package gui

import (
	"strings"

	"github.com/jesseduffield/lazygit/pkg/ui"
)

// Render draws the whole UI.
func (gui *Gui) Render() error {
	gui.Screen = NewScreen(gui.Width, gui.Height)
	l := gui.ComputeLayout()
	gui.placeViews(l)
	for _, name := range []string{"status", "files", "branches", "commits", "stash"} {
		if v, ok := gui.Views[name]; ok && v.Visible {
			gui.renderView(gui.Screen, v)
		}
	}
	for _, name := range []string{"worktrees", "submodules", "remotes", "tags", "reflog"} {
		if v, ok := gui.Views[name]; ok && v.Visible {
			gui.renderView(gui.Screen, v)
		}
	}
	if v, ok := gui.Views["main"]; ok && v.Visible {
		gui.renderView(gui.Screen, v)
	}
	if v, ok := gui.Views["cmdLog"]; ok && v.Visible {
		gui.renderView(gui.Screen, v)
	}
	if gui.Config.Gui.ShowBottomLine {
		gui.renderInfoLine(gui.Screen)
	}
	for i := range gui.Popups {
		gui.renderPopup(gui.Screen, &gui.Popups[i])
	}
	var out strings.Builder
	gui.Screen.Flush(&out)
	gui.Term.Write([]byte(out.String()))
	return nil
}

// placeViews sets the geometry and titles of all views.
func (gui *Gui) placeViews(l *Layout) {
	// side panels
	y := 0
	for i, w := range gui.Windows {
		h := 0
		if i < len(l.Sections) {
			h = l.Sections[i]
		}
		tab := gui.WindowTab[i]
		if tab >= len(w.Contexts) {
			tab = 0
			gui.WindowTab[i] = 0
		}
		ctx := w.Contexts[tab]
		v := gui.Views[ctx.View]
		if v == nil {
			y += h
			continue
		}
		v.X = 0
		v.Y = y
		v.W = l.SideWidth
		v.H = h
		v.Visible = l.ShowSide && h > 0
		v.Focused = gui.CurrentContextKey == ctx.Key && l.ShowSide
		v.BorderStyle = gui.borderStyle(v.Focused)
		v.SelectedStyle = gui.selectedStyle(true)
		v.InactiveSelectedStyle = gui.selectedStyle(false)
		v.JumpKey = w.JumpKey
		v.Tabs = gui.tabsForWindow(w)
		v.ActiveTab = tab
		gui.syncView(ctx, v)
		y += h
	}
	// main view
	mv := gui.Views["main"]
	if mv != nil {
		mv.X = l.SideWidth
		mv.Y = 0
		mv.W = l.MainWidth
		mv.H = l.MainHeight
		mv.Visible = l.ShowMain && l.MainHeight > 0
		ctx := gui.CurrentContext()
		focused := gui.CurrentContextKey == MainContext || ctx.Window < 0
		mv.Focused = focused && l.ShowMain
		mv.BorderStyle = gui.borderStyle(mv.Focused)
		mv.JumpKey = "0"
		mv.Title = ""
		mv.Tabs = nil
		if ctx.MainTitle != nil {
			mv.Title = ctx.MainTitle()
		}
		var lines []Line
		if ctx.MainContent != nil {
			lines = ctx.MainContent()
		}
		mv.Lines = lines
		mv.Footer = ""
		gui.syncSelection(mv)
	}
	// command log
	cl := gui.Views["cmdLog"]
	if cl != nil {
		cl.X = l.SideWidth
		cl.Y = l.MainHeight
		cl.W = l.MainWidth
		cl.H = l.CmdLogHeight
		cl.Visible = l.ShowMain && l.CmdLogHeight > 0
		cl.BorderStyle = gui.borderStyle(false)
		cl.JumpKey = ""
		cl.Title = "Command log"
		cl.Lines = gui.cmdLogLines()
		cl.Footer = ""
	}
	gui.lastLayout = l
}

func (gui *Gui) tabsForWindow(w *SideWindow) []Tab {
	var tabs []Tab
	for i, c := range w.Contexts {
		tabs = append(tabs, Tab{Name: c.Title, Index: i, Context: c.Key})
	}
	return tabs
}

// syncView updates a side view's content and selection.
func (gui *Gui) syncView(ctx *Context, v *View) {
	if ctx.GetLines != nil {
		v.Lines = ctx.GetLines()
	}
	v.Footer = ""
	if gui.Config.Gui.ShowListFooter {
		total := len(v.Lines)
		sel := v.Selected + 1
		if total == 0 {
			sel = 0
		}
		if sel > total {
			sel = total
		}
		v.Footer = strconv1(sel) + " of " + strconv1(total)
	}
	gui.syncSelection(v)
	v.ShowScrollbar = true
}

func strconv1(n int) string {
	if n < 0 {
		n = 0
	}
	digits := "0123456789"
	if n == 0 {
		return "0"
	}
	var b []byte
	for n > 0 {
		b = append([]byte{digits[n%10]}, b...)
		n /= 10
	}
	return string(b)
}

// syncSelection clamps the selection of a list view.
func (gui *Gui) syncSelection(v *View) {
	n := len(v.Lines)
	if n == 0 {
		v.Selected = -1
		return
	}
	if v.Selected < 0 {
		v.Selected = 0
	}
	if v.Selected >= n {
		v.Selected = n - 1
	}
}

func (gui *Gui) cmdLogLines() []Line {
	lines := []Line{NewLine("You can hide/focus this panel by pressing '@'"), NewLine("")}
	if gui.Config.Gui.ShowRandomTip {
		tip := gui.randomTip()
		for _, l := range wrapText("Random tip: "+tip, gui.cmdLogWidth()) {
			lines = append(lines, NewLine(l))
		}
	}
	lines = append(lines, gui.CommandLog...)
	return lines
}

func (gui *Gui) cmdLogWidth() int {
	if v := gui.Views["cmdLog"]; v != nil {
		return v.InnerWidth() - 2
	}
	return 70
}

// wrapText wraps text to a width.
func wrapText(s string, w int) []string {
	if w <= 0 {
		return []string{s}
	}
	var out []string
	words := strings.Split(s, " ")
	cur := ""
	for _, word := range words {
		candidate := word
		if cur != "" {
			candidate = cur + " " + word
		}
		if len(candidate) > w && cur != "" {
			out = append(out, cur)
			cur = word
		} else {
			cur = candidate
		}
	}
	if cur != "" {
		out = append(out, cur)
	}
	return out
}

// renderInfoLine draws the bottom line.
func (gui *Gui) renderInfoLine(s *Screen) {
	y := gui.Height - 1
	left := gui.optionsText()
	right := gui.rightSideText()
	leftWidth := runeLen(left)
	rightWidth := runeLen(right)
	style := ui.Style{Fg: "blue"}
	x := 0
	avail := gui.Width - rightWidth - 1
	if avail < 0 {
		avail = 0
	}
	text := left
	if leftWidth > avail {
		text = truncateOptions(left, avail)
	}
	s.SetText(0, y, runeLen(text), text, style)
	// pad the rest of the options run with spaces
	gap := gui.Width - rightWidth - runeLen(text)
	if gap > 0 {
		s.SetText(runeLen(text), y, gap, strings.Repeat(" ", gap), style)
	}
	// right side
	x = gui.Width - rightWidth
	s.SetText(x, y, rightWidth, right, ui.DefaultStyle)
}

func truncateOptions(s string, avail int) string {
	if avail <= 0 {
		return ""
	}
	parts := strings.Split(s, " | ")
	var cur strings.Builder
	for i, p := range parts {
		candidate := p
		if i > 0 {
			candidate = cur.String() + " | " + p
		}
		if runeLen(candidate) > avail {
			// add ellipsis if it fits
			if cur.Len() > 0 {
				candidate = cur.String() + " | \u2026"
				if runeLen(candidate) <= avail {
					return candidate
				}
			}
			// otherwise truncate the current prefix
			break
		}
		cur.Reset()
		cur.WriteString(candidate)
	}
	out := cur.String()
	if runeLen(out) > avail {
		out = out[:avail]
	}
	return out
}

func (gui *Gui) rightSideText() string {
	return "Donate Ask Question " + Version()
}

