package gui

import (
	"strings"

	"github.com/jesseduffield/lazygit/pkg/ui"
)

// ShowPopup displays a popup window.
func (gui *Gui) ShowPopup(p Popup) {
	gui.Popups = append(gui.Popups, p)
	gui.layoutPopups()
}

// ClosePopup closes the topmost popup.
func (gui *Gui) ClosePopup() error {
	if len(gui.Popups) == 0 {
		return nil
	}
	p := gui.Popups[len(gui.Popups)-1]
	gui.Popups = gui.Popups[:len(gui.Popups)-1]
	if p.OnClose != nil {
		return p.OnClose(gui)
	}
	return nil
}

// TopPopup returns the topmost popup.
func (gui *Gui) TopPopup() *Popup {
	if len(gui.Popups) == 0 {
		return nil
	}
	return &gui.Popups[len(gui.Popups)-1]
}

// layoutPopups computes the geometry of the popups.
func (gui *Gui) layoutPopups() {
	for i := range gui.Popups {
		p := &gui.Popups[i]
		innerW := 78
		if gui.Width-2 < innerW {
			innerW = gui.Width - 2
		}
		lines := p.wrappedLines(innerW)
		height := len(lines) + 2
		maxH := gui.Height - 4
		if maxH < 3 {
			maxH = 3
		}
		if height > maxH {
			height = maxH
		}
		width := innerW + 2
		p.X = (gui.Width - width) / 2
		if p.X < 0 {
			p.X = 0
		}
		p.Y = (gui.Height - height) / 2
		p.Width = width
		p.Height = height
		p.Select = 0
		p.ScrollTop = 0
	}
}

// wrappedLines returns the popup content lines wrapped to the width.
func (p *Popup) wrappedLines(w int) []Line {
	var out []Line
	for _, l := range p.Lines {
		text := lineString(l)
		for _, chunk := range wrapText(text, w) {
			out = append(out, NewLine(chunk))
		}
	}
	return out
}

func lineString(l Line) string {
	var b strings.Builder
	for _, r := range l.Runs {
		b.WriteString(r.Text)
	}
	return b.String()
}

// renderPopup renders a popup on the screen.
func (gui *Gui) renderPopup(s *Screen, p *Popup) {
	chars := borderChars(gui.Config.Gui.Border)
	bs := gui.borderStyle(true)
	innerW := p.Width - 2
	innerH := p.Height - 2
	// top border with title
	s.SetCell(p.X, p.Y, chars.TopLeft, bs)
	title := "\u2500" + p.Title
	col := p.X + 1
	for _, r := range title {
		if col >= p.X+p.Width-1 {
			break
		}
		style := ui.Style{Fg: "default"}
		if r == '\u2500' {
			style = bs
		}
		s.SetCell(col, p.Y, r, style)
		col++
	}
	for c := col; c < p.X+p.Width-1; c++ {
		s.SetCell(c, p.Y, chars.Horizontal, bs)
	}
	s.SetCell(p.X+p.Width-1, p.Y, chars.TopRight, bs)
	// bottom border
	by := p.Y + p.Height - 1
	s.SetCell(p.X, by, chars.BottomLeft, bs)
	for c := p.X + 1; c < p.X+p.Width-1; c++ {
		s.SetCell(c, by, chars.Horizontal, bs)
	}
	s.SetCell(p.X+p.Width-1, by, chars.BottomRight, bs)
	if p.Footer != "" {
		w := runeLen(p.Footer)
		s.SetText(p.X+p.Width-2-w, by, w, p.Footer, ui.Style{Fg: "default"})
	} else if p.Footer == "" && p.Height > 2 {
		// show selection footer for menus
	}
	// content
	lines := p.wrappedLines(innerW)
	if len(lines) == 0 && p.HasInput {
		lines = []Line{NewLine(p.Prompt + p.Input)}
	}
	for i := 0; i < innerH; i++ {
		idx := p.ScrollTop + i
		y := p.Y + 1 + i
		style := ui.DefaultStyle
		if idx >= 0 && idx < len(lines) {
			s.SetText(p.X+1, y, innerW, lineString(lines[idx]), style)
		}
	}
	if p.HasInput {
		// input row
		y := p.Y + 1
		s.SetText(p.X+1, y, innerW, p.Prompt+p.Input, ui.DefaultStyle)
		if gui.Searching || p.Editable {
			cx := p.X + 1 + runeLen(p.Prompt) + runeLen(p.Input)
			s.SetCell(cx, y, '_', ui.Style{Fg: "cyan", Bold: true})
		}
	}
	// footer "n of m"
	if len(lines) > 0 {
		total := len(lines)
		sel := 1
		if p.Select >= 0 && p.Select < total {
			sel = p.Select + 1
		}
		text := strconv1(sel) + " of " + strconv1(total)
		w := runeLen(text)
		s.SetText(p.X+p.Width-2-w, by, w, text, ui.Style{Fg: "default"})
	}
}

