		gui.setScreenMode(1)
		return nil
	case name == kb.PrevScreenMode:
		gui.setScreenMode(-1)
		return nil
	case name == kb.OptionMenuAlt1:
		return gui.showKeybindingsMenu()
	case name == kb.ExtrasMenu:
		return gui.showExtrasMenu()
	case name == kb.StartSearch:
		gui.startSearch()
		return nil
	case name == kb.FocusMainView:
		gui.focusMain()
		return nil
	case name == kb.OpenRecentRepos:
		return gui.showRecentRepos()
	case name == kb.Refresh:
		gui.Refresh()
		gui.logCommand("git refresh")
		return nil
	case name == kb.ScrollUpMain, name == kb.ScrollUpMainAlt1:
		gui.scrollMain(-3)
		return nil
	case name == kb.ScrollDownMain, name == kb.ScrollDownMainAlt1:
		gui.scrollMain(3)
		return nil
	case name == kb.ScrollUpMainAlt2:
		gui.scrollMain(-gui.mainInnerHeight() / 2)
		return nil
	case name == kb.ScrollDownMainAlt2:
		gui.scrollMain(gui.mainInnerHeight() / 2)
		return nil
	case name == kb.ScrollUpMain && false:
		return nil
	}
	// panel jump keys
	if len(name) == 1 && name >= "1" && name <= "5" {
		idx := int(name[0] - '1')
		if idx < len(gui.Windows) {
			gui.jumpToWindow(idx)
			return nil
		}
	}
	// context specific
	ctx := gui.CurrentContext()
	for _, b := range gui.keybindingsFor(ctx.Key) {
		if b.Key == name {
			if b.Disabled != nil && b.Disabled() {
				return nil
			}
			if b.Handler != nil {
				return b.Handler(gui)
			}
			return nil
		}
	}
	return nil
}

func (gui *Gui) keybindingsFor(key ContextKey) []Keybinding {
	return gui.contextKeybindings[key]
}

// handlePopupKey handles keys while a popup is open.
func (gui *Gui) handlePopupKey(p *Popup, name string) error {
	un := gui.Config.Keybinding.Universal
	switch name {
	case un.Return, un.QuitAlt1:
		if p.Cancel != nil {
			p.Cancel(gui)
		}
		return gui.ClosePopup()
	case un.Confirm, un.ConfirmMenu, un.GoInto, un.Select:
		if p.OnConfirm != nil {
			return p.OnConfirm(gui, p.Input)
		}
		return gui.ClosePopup()
	}
	return nil
}

// handleSearchKey handles keys while searching.
func (gui *Gui) handleSearchKey(name string) error {
	un := gui.Config.Keybinding.Universal
	switch name {
	case un.Return, un.Confirm:
		gui.Searching = false
		gui.search(gui.SearchString)
		return nil
	case "<esc>":
		gui.Searching = false
		gui.SearchString = ""
		return nil
	case "<backspace>":
		if len(gui.SearchString) > 0 {
			r := []rune(gui.SearchString)
			gui.SearchString = string(r[:len(r)-1])
		}
		return nil
	}
	if len(name) == 1 {
		gui.SearchString += name
	}
	return nil
}
