package gui

import (
	"os"
	"os/signal"
	"syscall"
	"time"

	"github.com/jesseduffield/lazygit/pkg/ui"
)

// Run starts the GUI event loop.
func (gui *Gui) Run() error {
	gui.Term.Enter()
	defer gui.Term.Close()
	gui.Refresh()
	gui.checkStartupPopups()
	gui.Render()

	sigwinch := make(chan os.Signal, 1)
	signal.Notify(sigwinch, syscall.SIGWINCH, syscall.SIGTERM, syscall.SIGINT)
	go func() {
		for range sigwinch {
			w, h := gui.Term.RefreshSize()
			gui.Width, gui.Height = w, h
			gui.Render()
		}
	}()

	buf := make([]byte, 256)
	ticker := time.NewTicker(time.Duration(gui.Config.Refresher.RefreshInterval) * time.Second)
	defer ticker.Stop()
	fetchTicker := time.NewTicker(time.Duration(gui.Config.Refresher.FetchInterval) * time.Second)
	defer fetchTicker.Stop()

	for !gui.Quitting {
		gui.Term.SetMouse(gui.Config.Gui.MouseEvents)
		n, err := gui.Term.Read(buf)
		if err != nil {
			if n == 0 {
				continue
			}
			return nil
		}
		keys, _ := ui.ParseKeys(buf[:n])
		quit := false
		for _, k := range keys {
			if err := gui.HandleKey(k); err != nil {
				return err
			}
			if gui.Quitting {
				quit = true
				break
			}
		}
		if quit {
			break
		}
		gui.Render()
		select {
		case <-ticker.C:
			if gui.Config.Git.AutoRefresh {
				gui.Refresh()
				gui.Render()
			}
		case <-fetchTicker.C:
			if gui.Config.Git.AutoFetch {
				gui.Refresh()
				gui.Render()
			}
		default:
		}
	}
	gui.saveState()
	return nil
}

// checkStartupPopups shows the first-use popup if needed.
func (gui *Gui) checkStartupPopups() {
	if gui.Config.DisableStartupPopups {
		return
	}
	if gui.AppState.StartupPopupVersion < 5 {
		gui.ShowPopup(gui.startupPopup())
	}
}

// saveState persists the app state.
func (gui *Gui) saveState() {
	if gui.AppState != nil {
		gui.AppState.Save()
	}
}

