package app

import (
	"fmt"
	"log"
	"os"
	"path/filepath"
	"strings"

	"github.com/jesseduffield/lazygit/pkg/commands"
	"github.com/jesseduffield/lazygit/pkg/config"
	"github.com/jesseduffield/lazygit/pkg/gui"
	"github.com/jesseduffield/lazygit/pkg/state"
	"github.com/jesseduffield/lazygit/pkg/ui"
)

// AppConfig holds the parsed CLI arguments.
type AppConfig struct {
	Debug          bool
	Version        bool
	PrintVersionInfo bool
	PrintConfig    bool
	PrintConfigDir bool
	UseConfigDir   string
	UseConfigFile  string
	FilterPath     string
	FilterPathIsFunc bool
	RepoPath       string
	WorkTree       string
	GitDir         string
	ScreenMode     string
	ArgMode        string
}

// CliArgs holds the parsed command line arguments.
type CliArgs struct {
	Arg      string
	RepoPath string
}

// Start begins the application.
func Start(config *config.AppConfig, appState *state.AppState, cliArgs CliArgs) error {
	gc, err := commands.NewGitCommand(config.RepoPath, config.GitDir, config.WorkTree)
	if err != nil {
		return err
	}
	gui, err := NewGui(config, appState, gc, cliArgs)
	if err != nil {
		return err
	}
	return gui.Run()
}

// NewGui creates a Gui from the app config.
func NewGui(config *config.AppConfig, appState *state.AppState, gc *commands.GitCommand, cliArgs CliArgs) (*gui.Gui, error) {
	gui := gui.NewGui(config.UserConfig, appState, gc)
	gui.RepoPath = config.RepoPath
	if config.WorkTree != "" {
		gui.WorkTree = config.WorkTree
	}
	if config.GitDir != "" {
		gui.GitDir = config.GitDir
	}
	gui.RepoName = filepath.Base(config.RepoPath)
	gui.FilterPath = config.FilterPath
	if config.ScreenMode != "" {
		gui.ScreenMode = config.ScreenMode
	}
	term, err := ui.NewTerminal()
	if err != nil {
		return nil, err
	}
	gui.SetTerm(term)
	return gui, nil
}

// validGitArgs are the accepted positional arguments.
var validGitArgs = []string{"status", "branch", "log", "stash"}

// ValidateArg validates a positional argument.
func ValidateArg(arg string) error {
	for _, a := range validGitArgs {
		if a == arg {
			return nil
		}
	}
	return fmt.Errorf("Invalid git arg value: '%s'. Must be one of the following values: %s. e.g. 'lazygit status'. See 'lazygit --help'.", arg, strings.Join(validGitArgs, ", "))
}

// usageTemplate is the help text.
func usageText(name string) string {
	return fmt.Sprintf(`%s

  Usage:
    %s [git-arg]

  Positional Variables: 
    git-arg   Panel to focus upon opening lazygit. Accepted values (based on git terminology): status, branch, log, stash. Ignored if --filter arg is passed.
  Flags: 
    -h --help               Displays help with available flag, subcommand, and positional value parameters.
    -p --path               Path of git repo. (equivalent to --work-tree=<path> --git-dir=<path>/.git/)
    -f --filter             Path to filter on in `+"`git log -- <path>`"+`. When in filter mode, the commits, reflog, and stash are filtered based on the given path, and some operations are restricted
    -v --version            Print the current version
    -d --debug              Run in debug mode with logging (see --logs flag below). Use the LOG_LEVEL env var to set the log level (debug/info/warn/error)
    -l --logs               Tail lazygit logs (intended to be used when `+"`lazygit --debug`"+` is called in a separate terminal tab)
       --profile            Start the profiler and serve it on http port 6060. See CONTRIBUTING.md for more info.
    -c --config             Print the default config
    -cd --print-config-dir   Print the config directory
    -ucd --use-config-dir     override default config directory with provided directory
    -w --work-tree          equivalent of the --work-tree git argument
    -g --git-dir            equivalent of the --git-dir git argument
    -ucf --use-config-file    Comma separated list to custom config file(s)
    -sm --screen-mode        The initial screen-mode, which determines the size of the focused panel. Valid options: 'normal' (default), 'half', 'full'

`, name, name)
}

// VersionString returns the version line.
func VersionString(gitVersion string) string {
	return fmt.Sprintf("commit=%s, build date=%s, build source=%s, version=%s, os=%s, arch=%s, git version=%s",
		gui.CommitHash, gui.BuildDate, gui.BuildSource, gui.Version(), os_GOOS(), os_GOARCH(), gitVersion)
}

func os_GOOS() string   { return "linux" }
func os_GOARCH() string { return "amd64" }

// Fatal prints an error and exits.
func Fatal(err error) {
	log.Fatalf("An error occurred! Please create an issue at: https://github.com/jesseduffield/lazygit/issues\n\n%v", err)
}
