	if gui.Config.DisableStartupPopups {
		return
	}
	if gui.AppState.StartupPopupVersion < 5 {
		gui.ShowPopup(gui.startupPopup())
	}
}

// saveState persists the app state.
func (gui *Gui) saveState() {
	if gui.AppState != nil {
		gui.AppState.Save()
	}
