// parseArgs parses the command line arguments.
func parseArgs(args []string) (*AppConfig, error) {
	cfg := &AppConfig{programName: "lazygit"}
	if len(args) > 0 {
		cfg.programName = args[0]
	}
	i := 1
	for i < len(args) {
		a := args[i]
		switch a {
		case "-h", "--help":
			cfg.ShowHelp = true
			i++
		case "-v", "--version":
			cfg.ShowVersion = true
			i++
		case "-c", "--config":
			cfg.PrintConfig = true
			i++
		case "-cd", "--print-config-dir":
			cfg.PrintConfigDir = true
			i++
		case "-l", "--logs":
			cfg.TailLogs = true
			i++
		case "-d", "--debug":
			cfg.Debug = true
			i++
		case "--profile":
			i++
		case "-p", "--path":
			if i+1 >= len(args) {
				return nil, &usageError{msg: fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", flagName(a)), code: 2}
			}
			cfg.RepoPath = args[i+1]
			i += 2
		case "-w", "--work-tree":
			if i+1 >= len(args) {
				return nil, &usageError{msg: fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", flagName(a)), code: 2}
			}
			cfg.WorkTree = args[i+1]
			i += 2
		case "-g", "--git-dir":
			if i+1 >= len(args) {
				return nil, &usageError{msg: fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", flagName(a)), code: 2}
			}
			cfg.GitDir = args[i+1]
			i += 2
		case "-f", "--filter":
			if i+1 >= len(args) {
				return nil, &usageError{msg: fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", flagName(a)), code: 2}
			}
			cfg.FilterPath = args[i+1]
			i += 2
		case "-sm", "--screen-mode":
			if i+1 >= len(args) {
				return nil, &usageError{msg: fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", flagName(a)), code: 2}
			}
			cfg.ScreenMode = args[i+1]
			i += 2
		case "-ucd", "--use-config-dir":
			if i+1 >= len(args) {
				return nil, &usageError{msg: fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", flagName(a)), code: 2}
			}
			cfg.ConfigPaths = append(cfg.ConfigPaths, config.ConfigDirFromPath(args[i+1]))
			i += 2
		case "-ucf", "--use-config-file":
			if i+1 >= len(args) {
				return nil, &usageError{msg: fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", flagName(a)), code: 2}
			}
			for _, p := range strings.Split(args[i+1], ",") {
				if p != "" {
					cfg.ConfigPaths = append(cfg.ConfigPaths, p)
				}
			}
			i += 2
		default:
			if strings.HasPrefix(a, "-") {
				return nil, &usageError{msg: helpText(cfg.programName) + "Unknown arguments supplied:  " + strings.TrimPrefix(a, "--"), code: 2}
			}
			if len(a) == 2 && strings.HasPrefix(a, "-") {
				return nil, &usageError{msg: helpText(cfg.programName) + fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", a[1:]), code: 2}
			}
			if err := app.ValidateArg(a); err != nil {
				log.Println(err)
				os.Exit(1)
			}
			cfg.CliArgs.Arg = a
			i++
		}
	}
	return cfg, nil
}

func flagName(a string) string {
	return strings.TrimLeft(a, "-")
}

func helpText(name string) string {
	return app.UsageText(name)
}
