import (
	"fmt"
	"log"
	"os"
	"strconv"
	"strings"

	"github.com/jesseduffield/lazygit/pkg/app"
	"github.com/jesseduffield/lazygit/pkg/commands"
	"github.com/jesseduffield/lazygit/pkg/config"
	"github.com/jesseduffield/lazygit/pkg/state"
)

func main() {
	appConfig, err := parseArgs(os.Args)
	if err != nil {
		if _, ok := err.(*usageError); ok {
			fmt.Print(app.UsageText(appConfig.programName))
			if err.Error() != "" {
				fmt.Fprintln(os.Stderr, err.Error())
			}
			os.Exit(errExitCode(err))
			return
		}
	}
	if appConfig.ShowHelp {
		fmt.Print(app.UsageText(appConfig.programName))
		return
	}
	gc := &commands.GitCommand{}
	gitVersion := gc.GitVersion()
	if appConfig.ShowVersion {
		fmt.Println(app.VersionString(gitVersion))
		return
	}
	if appConfig.PrintConfig {
		fmt.Print(config.EncodeYAML(config.UserConfigDefaults()) + "\n")
		return
	}
	if appConfig.PrintConfigDir {
		fmt.Println(config.ConfigDir())
		return
	}
	if appConfig.TailLogs {
		tailLogs()
		return
	}

	appState := state.LoadAppState()

	// determine the repo path
	repoPath := appConfig.RepoPath
	if repoPath == "" {
		cwd, _ := os.Getwd()
		repoPath = cwd
	}
	config.UserConfigPaths = appConfig.ConfigPaths
	userConfig, err := config.LoadUserConfig(appConfig.ConfigPaths)
	if err != nil {
		log.Fatalf("An error occurred! Please create an issue at: https://github.com/jesseduffield/lazygit/issues\n\n%v", err)
	}
	appConfig.UserConfig = userConfig
	appConfig.AppState = appState
	appConfig.GitVersion = gitVersion

	err = app.Run(appConfig, appState, appConfig.CliArgs)
	if err != nil {
		log.Fatalf("An error occurred! Please create an issue at: https://github.com/jesseduffield/lazygit/issues\n\n%v", err)
	}
}

func tailLogs() {
	path := config.StateDir() + "/development.log"
	fmt.Printf("Tailing log file %s\n\n", path)
	if _, err := os.Stat(path); err != nil {
		log.Println("Log file does not exist. Run `lazygit --debug` first to create the log file")
		return
	}
	followFile(path)
}

func followFile(path string) {
	buf := make([]byte, 4096)
	offset := int64(0)
	for {
		f, err := os.Open(path)
		if err != nil {
			return
		}
		fi, _ := f.Stat()
		if fi.Size() > offset {
			f.Seek(offset, 0)
			n, _ := f.Read(buf)
			if n > 0 {
				os.Stdout.Write(buf[:n])
				offset += int64(n)
			}
		}
		f.Close()
		select {}
	}
}

