				return nil, &usageError{msg: fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", flagName(a)), code: 2}
			}
			cfg.ConfigPaths = append(cfg.ConfigPaths, config.ConfigDirFromPath(args[i+1]))
			i += 2
		case "-ucf", "--use-config-file":
			if i+1 >= len(args) {
				return nil, &usageError{msg: fmt.Sprintf("Expected a following arg for flag %s, but it did not exist.", flagName(a)), code: 2}
			}
			for _, p := range strings.Split(args[i+1], ",") {
				if p != "" {
					cfg.ConfigPaths = append(cfg.ConfigPaths, p)
				}
			}
