new='''// fileTreeLines builds the file tree.
func (gui *Gui) fileTreeLines() []Line {
	files := gui.StatusFiles
	if len(files) == 0 {
		return []Line{}
	}
	sorted := make([]commands.StatusFile, len(files))
	copy(sorted, files)
	sort.SliceStable(sorted, func(i, j int) bool { return sorted[i].Name < sorted[j].Name })
	gui.StatusFiles = sorted

	type node struct {
		name     string
		isDir    bool
		children []*node
		expanded bool
		file     *commands.StatusFile
	}
	root := &node{name: "", isDir: true, expanded: true}
	index := map[string]*node{"": root}
	for i := range gui.StatusFiles {
		f := &gui.StatusFiles[i]
		parts := strings.Split(f.Name, "/")
		cur := root
		path := ""
		for pi, p := range parts {
			last := pi == len(parts)-1
			if path == "" {
				path = p
			} else {
				path = path + "/" + p
			}
			if last {
				cur.children = append(cur.children, &node{name: p, isDir: false, expanded: true, file: f})
			} else {
				n, ok := index[path]
				if !ok {
					n = &node{name: p, isDir: true, expanded: true}
					index[path] = n
					cur.children = append(cur.children, n)
				}
				cur = n
			}
		}
	}
	// collapse chains of single child directories
	var collapse func(n *node) *node
	collapse = func(n *node) *node {
		for n.isDir && len(n.children) == 1 && n.children[0].isDir {
			child := n.children[0]
			n = &node{name: n.name + "/" + child.name, isDir: true, expanded: n.expanded, children: child.children}
		}
		for i, c := range n.children {
			n.children[i] = collapse(c)
		}
		return n
	}
	root = collapse(root)
	// sort children: directories first, then files, alphabetically
	var sortNodes func(n *node)
	sortNodes = func(n *node) {
		sort.SliceStable(n.children, func(i, j int) bool {
			a, b := n.children[i], n.children[j]
			if a.isDir != b.isDir {
				return a.isDir
			}
			return a.name < b.name
		})
		for _, c := range n.children {
			sortNodes(c)
		}
	}
	sortNodes(root)

	var lines []Line
	if !gui.Config.Gui.ShowFileTree {
		for i := range gui.StatusFiles {
			lines = append(lines, gui.fileLine(gui.StatusFiles[i].Name, 0, &gui.StatusFiles[i]))
		}
		return lines
	}
	var walk func(n *node, depth int, isRoot bool)
	walk = func(n *node, depth int, isRoot bool) {
		if n.isDir {
			marker := "\\u25bc"
			if !n.expanded {
				marker = "\\u25b6"
			}
			prefix := strings.Repeat(" ", depth*2)
			name := n.name
			if isRoot {
				name = "/"
			}
			runs := []ui.Run{{Text: prefix + marker + " " + name, Style: ui.Style{Fg: "default"}}}
			lines = append(lines, Line{Runs: runs})
			if n.expanded {
				for _, c := range n.children {
					walk(c, depth+1, false)
				}
			}
			return
		}
		lines = append(lines, gui.fileLine(n.file.Name, depth, n.file))
	}
	if root.isDir && len(root.children) == 1 && !root.children[0].isDir {
		// single file at the root: no root item
		walk(root.children[0], 0, false)
		return lines
	}
	walk(root, 0, true)
	return lines
}

'''
