		for pi, p := range parts {
			last := pi == len(parts)-1
			if path == "" {
				path = p
			} else {
				path = path + "/" + p
			}
			if last {
				cur.children = append(cur.children, &node{name: p, isDir: false, expanded: true, file: f})
			} else {
				n, ok := index[path]
				if !ok {
					n = &node{name: p, isDir: true, expanded: true}
