new='''// GetStatusFiles parses `git status --porcelain` output.
func (g *GitCommand) GetStatusFiles() ([]StatusFile, error) {
	out, err := g.Run("status", "--untracked-files=all", "--porcelain", "-z", "--find-renames=50%")
	if err != nil {
		return nil, err
	}
	var files []StatusFile
	for _, chunk := range strings.Split(out, "\\x00") {
		if chunk == "" {
			continue
		}
		lines := strings.Split(chunk, "\\n")
		if len(lines) == 0 {
			continue
		}
		first := lines[0]
		if len(first) < 2 {
			continue
		}
		status := first[:2]
		name := ""
		if len(first) > 3 {
			name = first[3:]
		}
		f := StatusFile{ShortStatus: status, Name: name, Tracked: true}
		x, y := status[0], status[1]
		switch x {
		case 'M', 'A', 'D', 'R', 'C':
			f.HasStagedChanges = true
		case '?':
			f.Tracked = false
		}
		switch y {
		case 'M', 'D', 'R', 'C':
			f.HasUnstagedChanges = true
		case '?':
			f.Tracked = false
		}
		if x == 'R' || y == 'R' {
			if len(lines) > 1 && strings.HasPrefix(lines[1], "original ") {
				f.PreviousName = strings.TrimPrefix(lines[1], "original ")
			}
		}
		files = append(files, f)
	}
	return files, nil
}

