func (gui *Gui) branchLines() []Line {
	width := 0
	for i := range gui.Branches {
		if !gui.Branches[i].Head {
			if l := len(gui.recency(gui.Branches[i].CommitDate)); l > width {
				width = l
			}
		}
	}
	var lines []Line
	for i := range gui.Branches {
		b := &gui.Branches[i]
		branchStyle := ui.Style{Fg: "default"}
		recency := ""
		if !b.Head {
			recency = gui.recency(b.CommitDate)
		}
		markerStyle := ui.Style{Fg: "default"}
		if b.Head {
			markerStyle = ui.Style{Fg: "green"}
		}
		runs := []ui.Run{}
		if recency != "" {
			runs = append(runs, ui.Run{Text: recency, Style: ui.Style{Fg: "cyan"}})
		}
		if pad := width - len(recency); pad > 0 {
			runs = append(runs, ui.Run{Text: strings.Repeat(" ", pad), Style: markerStyle})
		}
		runs = append(runs, ui.Run{Text: gui.markerFor(b), Style: markerStyle})
		runs = append(runs, ui.Run{Text: " " + b.Name, Style: ui.Style{Fg: "default"}})
		if track := gui.trackSymbol(b.Pullables); track != "" {
			runs = append(runs, ui.Run{Text: " " + track, Style: ui.Style{Fg: "default"}})
		}
		lines = append(lines, Line{Runs: runs})
	}
	return lines
}

// markerFor returns the branch marker character.
func (gui *Gui) markerFor(b *commands.Branch) string {
	if b.Head {
