func (v *View) ContentLines() []Line {
	if !v.Wrap {
		return v.Lines
	}
	w := v.InnerWidth()
	if w <= 0 {
		return v.Lines
	}
	var out []Line
	for _, l := range v.Lines {
		if lineRuneLen(l) <= w {
			out = append(out, l)
			continue
		}
		// hard wrap preserving run styles
		cur := Line{}
		count := 0
		for _, r := range l.Runs {
			text := r.Text
			for len(text) > 0 {
				if count == w {
					out = append(out, cur)
					cur = Line{}
					count = 0
				}
				room := w - count
				// split on rune boundaries
				n := 0
				i := 0
				for i < len(text) {
					_, size := decodeRuneSize(text[i:])
					if n == room {
						break
					}
					i += size
					n++
				}
				chunk := text[:i]
				cur.Runs = append(cur.Runs, ui.Run{Text: chunk, Style: r.Style})
				count += n
				text = text[i:]
			}
		}
		if len(cur.Runs) > 0 {
			out = append(out, cur)
		}
	}
	return out
}

func lineRuneLen(l Line) int {
	n := 0
	for _, r := range l.Runs {
		n += len([]rune(r.Text))
	}
	return n
}

func decodeRuneSize(b []byte) (rune, int) {
	c := b[0]
	switch {
	case c < 0x80:
		return rune(c), 1
	case c&0xe0 == 0xc0 && len(b) >= 2:
		return rune(c&0x1f)<<6 | rune(b[1]&0x3f), 2
	case c&0xf0 == 0xe0 && len(b) >= 3:
		return rune(c&0x0f)<<12 | rune(b[1]&0x3f)<<6 | rune(b[2]&0x3f), 3
	case c&0xf8 == 0xf0 && len(b) >= 4:
		return rune(c&0x07)<<18 | rune(b[1]&0x3f)<<12 | rune(b[2]&0x3f)<<6 | rune(b[3]&0x3f), 4
	}
	return rune(c), 1
}

'''
